import json
from pathlib import Path
models=[]
def N(id,slot,label,caption,definition):return dict(id=id,slot=slot,label=label,caption=caption,definition=definition)
def E(id,a,b,label):return dict(id=id,fromId=a,toId=b,label=label)
def S(title,body,edge):return dict(title=title,body=body,edges=edge if isinstance(edge,list) else [edge])
def M(id,ch,section,title,intro,nodes,edges,steps,example,limits,mistakes,question,answer,refs=[]):
 models.append(dict(id=id,chapter=ch,section=section,title=title,intro=intro,nodes=nodes,edges=edges,steps=steps,example=example,limits=limits,mistakes=mistakes,check=dict(question=question,answer=answer),refs=refs))
M('layers','1','1.4','Phòng thủ nhiều lớp: một lỗ hổng chưa phải toàn bộ hệ thống','Theo dõi một file tải từ Internet đến máy người dùng: mỗi lớp giải quyết một loại rủi ro khác nhau.',[
 N('net','a','Internet','Nguồn bên ngoài','Nguồn gửi dữ liệu có thể hợp lệ hoặc không; cần kiểm tra thay vì mặc định tin cậy.'),N('fw','b','Firewall','Kiểm soát luồng','Tường lửa quyết định luồng nào được phép đi qua theo chính sách và khả năng kiểm tra của nó.'),N('host','c','Máy người dùng','Kiểm tra đầu cuối','Endpoint protection quan sát file, tiến trình và hành vi trên máy, kể cả nội dung đã được giải mã ở đầu cuối.'),N('rights','f','Quyền tối thiểu','Giới hạn thiệt hại','Least privilege chỉ cấp quyền cần thiết; một tài khoản thường không nên sửa mọi thành phần hệ thống.'),N('recover','e','Sao lưu & ứng phó','Khôi phục','Bản sao lưu sạch và quy trình ứng phó giúp khôi phục sau khi biện pháp ngăn chặn thất bại.')],
 [E('a','net','fw','1 · kết nối'),E('b','fw','host','2 · được phép'),E('c','host','rights','3 · thực thi'),E('d','rights','recover','4 · xử lý')],[
 S('Kiểm tra đường vào','Firewall xem luồng kết nối có đúng chính sách hay không. Cho phép HTTPS nghĩa là cho phép một loại luồng; nó không chứng minh mọi file bên trong đều lành tính. HTTPS bảo vệ kênh truyền, không chứng nhận ý định của nội dung.','a'),
 S('Kiểm tra nơi dữ liệu được sử dụng','File đến máy và được giải mã tại ứng dụng. Công cụ bảo vệ đầu cuối có thể kiểm tra file, chữ ký hoặc hành vi. Một lớp cần quan sát thứ mà lớp trước không thấy, thay vì chỉ lặp lại cùng một kiểm tra.','b'),
 S('Giảm quyền mà mã có thể sử dụng','Nếu file độc hại vẫn chạy, nó hoạt động trong bối cảnh quyền của tiến trình/tài khoản và các kiểm soát hệ điều hành. Quyền thấp làm giảm phạm vi tác động, nhưng không ngăn mọi hành vi: dữ liệu người dùng được phép đọc vẫn có thể bị ảnh hưởng.','c'),
 S('Khôi phục và rút kinh nghiệm','Khi phát hiện sự cố, cô lập, giữ bằng chứng cần thiết, xác định phạm vi rồi khôi phục từ nguồn sạch. Sao lưu chỉ hữu ích nếu bản sao không cùng bị phá và đã thử phục hồi. Đây là lớp giảm hậu quả, không thay thế việc phòng ngừa.','d')],
 'Một file độc hại đi qua kết nối HTTPS được cho phép. Endpoint có thể chặn nó; nếu không, quyền tối thiểu hạn chế tác động và bản sao lưu hỗ trợ phục hồi. Không lớp nào đơn độc bảo đảm kết quả.',
 'Hình là chuỗi kiểm soát minh họa, không phải mọi gói tin đi qua một thiết bị mang tên “quyền tối thiểu”. Trong thực tế các lớp còn song song, chồng lấp và phụ thuộc cấu hình.',
 ['Firewall không đồng nghĩa antivirus.','Mã hóa không tự loại bỏ malware.','Sao lưu là khả năng phục hồi, không phải bằng chứng chưa bị xâm nhập.'],
 'Firewall đã cho phép HTTPS; tại sao vẫn cần bảo vệ đầu cuối?','Vì đầu cuối thấy nội dung/hành vi sau giải mã, trong khi quyết định cho phép luồng không chứng minh file là an toàn.')
M('replay','1','1.2.3','Replay: thông điệp đúng nhưng bị dùng lại','Phân biệt kiểm tra “ai gửi, có bị sửa không” với kiểm tra “thông điệp có còn mới không”.',[
 N('alice','a','Người gửi','Thông điệp có tag','Người gửi hợp lệ tạo yêu cầu có MAC hoặc chữ ký.'),N('wire','b','Đường truyền','Bản tin có thể bị ghi lại','Đối phương có thể ghi lại nguyên một thông điệp mà không cần giải mã hoặc thay đổi nó.'),N('server','c','Máy nhận','Kiểm tra & xử lý','Máy nhận kiểm tra tính xác thực, tính mới và quyền thực hiện trước khi tác động trạng thái.'),N('record','e','Bản tin cũ','Gửi lại nguyên vẹn','Bản ghi giữ nguyên dữ liệu và tag nên kiểm tra xác thực đơn thuần có thể vẫn đạt.')],
 [E('send','alice','wire','1'),E('accept','wire','server','2'),E('copy','wire','record','3 · ghi lại'),E('repeat','record','server','4 · gửi lại')],[
 S('Tạo một yêu cầu hợp lệ','Alice gửi yêu cầu có dữ liệu và tag xác thực. Tag giúp phát hiện dữ liệu bị sửa và chứng minh người tạo biết khóa phù hợp; tự nó chưa cho biết yêu cầu này đã được xử lý lần nào.','send'),
 S('Máy nhận kiểm tra lần đầu','Nếu tag đúng và người gửi có quyền, yêu cầu được thực hiện. Nếu giao thức chưa ràng buộc một số thứ tự hay giá trị mới vào phần được xác thực, máy nhận có thể không có dấu hiệu phân biệt lần sau với lần đầu.','accept'),
 S('Ghi lại không đồng nghĩa bẻ khóa','Đối phương giữ nguyên bản tin hợp lệ đã đi qua. Không cần biết plaintext nếu có thể chuyển lại toàn bộ thông điệp được giao thức chấp nhận. Đây là lý do bảo mật nội dung và chống phát lại là hai vấn đề khác nhau.','copy'),
 S('Kiểm tra tính mới trước khi thực hiện','Lần gửi lại phải bị loại bằng nonce dùng một lần, số thứ tự/cửa sổ chống replay hoặc timestamp kết hợp kiểm tra phù hợp. Giá trị chống replay phải được ràng buộc vào MAC/chữ ký và máy nhận phải ghi nhận trạng thái; chỉ thêm một trường không kiểm tra là chưa đủ.','repeat')],
 'Một lệnh “thực hiện giao dịch X” đã có tag đúng không nên gây tác động lần hai. Mã giao dịch duy nhất và cơ chế xử lý idempotent có thể bổ sung cho chống replay của giao thức.',
 'Đây là mô hình logic; chi tiết nonce, đồng hồ và replay cache tùy giao thức. Không coi mọi gói lặp do mạng truyền lại là hành vi tấn công.',
 ['Tag vẫn đúng không có nghĩa thông điệp còn mới.','Timestamp không tự chống replay trong toàn bộ khoảng thời gian được chấp nhận.'],
 'Tại sao mã hóa yêu cầu vẫn chưa chắc chống replay?','Vì người ngoài có thể phát lại nguyên ciphertext mà không cần đọc nội dung; máy nhận còn phải kiểm tra tính mới.')
M('trojan','2a','2a.2','Trojan: từ vỏ bọc đến hành vi ngoài mong đợi','Mô hình nhận diện ranh giới tin cậy, không phải hướng dẫn tạo hoặc triển khai mã độc.',[
 N('source','a','Gói phần mềm','Vẻ ngoài hữu ích','Tên gọi, giao diện hoặc lời giới thiệu tạo kỳ vọng về chức năng của phần mềm.'),N('user','b','Người dùng','Quyết định chạy','Người dùng trao cơ hội thực thi khi chạy hoặc cho phép cài đặt.'),N('process','c','Tiến trình','Quyền đang có','Mã thực thi nhận bối cảnh quyền và các hạn chế mà hệ điều hành áp dụng.'),N('behavior','f','Hành vi phụ','Không đúng kỳ vọng','Hành vi có thể liên quan dữ liệu, cấu hình hoặc kết nối ngoài phạm vi chức năng đã công bố.'),N('observe','e','Giám sát & chặn','Đối chiếu bằng chứng','Log, tiến trình, quyền, file và kết nối được đối chiếu để đánh giá dấu hiệu bất thường.')],
 [E('a','source','user','1'),E('b','user','process','2'),E('c','process','behavior','3'),E('d','behavior','observe','4')],[
 S('Vỏ bọc tạo niềm tin','Trojan được nhận diện bởi việc giả dạng hoặc trình bày như phần mềm hữu ích trong khi có hành vi gây hại. Một chương trình có giao diện đẹp hoặc tên quen thuộc chưa được chứng minh an toàn chỉ vì nó giống phần mềm hợp lệ.','a'),
 S('Điểm chuyển ranh giới là thực thi','Khi chạy mã, người dùng trao khả năng hoạt động trong phạm vi quyền hiện có. Việc tải một file và việc thực thi file là hai sự kiện khác nhau; cần phân biệt chúng khi phân tích một tình huống lây nhiễm.','b'),
 S('Hành vi phụ sử dụng quyền và tài nguyên','Mã có thể làm việc không tương ứng với mục đích đã công bố. Không phải Trojan nào cũng điều khiển từ xa, tự khởi động hay cần quyền quản trị. Các khả năng đó tùy mẫu và môi trường, không phải điều kiện định nghĩa chung.','c'),
 S('Phòng thủ bằng quan sát nhiều nguồn','Đối chiếu nguồn phát hành, chữ ký phần mềm, thay đổi hệ thống, tiến trình và kết nối. Một dấu hiệu riêng lẻ chưa đủ kết luận: ứng dụng hợp lệ cũng kết nối Internet. Điều quan trọng là hành vi có cần thiết và được phép trong bối cảnh đó hay không.','d')],
 'Một ứng dụng học từ vựng yêu cầu quyền không liên quan và tạo kết nối không giải thích được cần được kiểm tra thêm. Không kết luận chỉ dựa trên tên ứng dụng hoặc một cổng đang mở.',
 'Sơ đồ chỉ trình bày cơ chế tin cậy và quan sát phòng thủ; không giả định mọi Trojan đều có máy chủ điều khiển hoặc một chuỗi hành vi cố định.',
 ['Trojan không được định nghĩa bởi khả năng tự nhân bản.','Cổng mở hoặc một process lạ chưa đủ chứng minh có Trojan.'],
 'Trojan và virus khác ở tiêu chí cốt lõi nào?','Trojan nhấn mạnh sự ngụy trang/hành vi gây hại; virus nhấn mạnh lây bằng cách gắn vào đối tượng chủ.')
M('keyboard-risk','2a','2a.3.2','Dữ liệu nhập: kênh truyền an toàn chưa bảo vệ mọi điểm','Nhìn vòng đời dữ liệu từ thiết bị nhập đến ứng dụng và kết nối mạng để hiểu rủi ro keylogger ở mức khái niệm.',[
 N('device','a','Thiết bị nhập','Phím bấm','Bàn phím hoặc thiết bị nhập tạo sự kiện trước khi ứng dụng xử lý nội dung.'),N('os','b','Hệ điều hành','Phân phối sự kiện','Hệ điều hành, driver và cơ chế nhập liệu chuyển thông tin đến nơi nhận phù hợp.'),N('app','c','Ứng dụng','Bản rõ tại đầu cuối','Ứng dụng cần thấy dữ liệu người dùng nhập để xử lý tác vụ.'),N('tls','f','Kênh TLS','Bảo vệ trên đường','Transport Layer Security bảo vệ dữ liệu trong kênh giữa hai đầu cuối sau thiết lập.'),N('dest','e','Dịch vụ đích','Nhận nội dung','Máy chủ hợp lệ xử lý dữ liệu sau khi kết nối được giải mã ở đầu nhận.')],
 [E('a','device','os','1'),E('b','os','app','2'),E('c','app','tls','3'),E('d','tls','dest','4')],[
 S('Dữ liệu xuất hiện trước TLS','Người dùng nhấn phím, hệ thống nhận các sự kiện nhập. TLS chưa tham gia ở đoạn này. Nếu có thiết bị ghi phím phần cứng trên đường tín hiệu, phần mềm quét file trên máy không nhất thiết quan sát được thiết bị đó.','a'),
 S('Rủi ro phụ thuộc điểm quan sát và quyền','Phần mềm không được phép có thể tìm cách quan sát dữ liệu đầu cuối; mức khả thi phụ thuộc quyền, hệ điều hành và các cơ chế bảo vệ. Không được suy ra mọi ứng dụng đều đọc được bàn phím của mọi ứng dụng khác.','b'),
 S('Ứng dụng cần dữ liệu để thực hiện chức năng','Trước khi gửi, ứng dụng thường phải xử lý bản rõ. Nếu chính ứng dụng hoặc máy đầu cuối bị xâm hại, việc mã hóa đường truyền không sửa được vấn đề đã xảy ra trước lúc dữ liệu vào kênh. Đây là khác biệt giữa bảo mật đầu cuối và bảo mật truyền tải.','c'),
 S('TLS vẫn có vai trò đúng phạm vi','TLS chống nghe trộm hoặc sửa thông điệp trên đường truyền theo mô hình của giao thức. Bảo vệ bổ sung gồm kiểm soát cài đặt, quyền, cập nhật, kiểm tra thiết bị vật lý và quan sát đầu cuối. Cần chọn biện pháp theo điểm dữ liệu bị lộ.','d')],
 'Nhập mật khẩu vào một ứng dụng trên máy không đáng tin cậy không trở nên an toàn chỉ vì trang có HTTPS. Ngược lại, điều này không có nghĩa HTTPS vô dụng: nó bảo vệ một ranh giới khác.',
 'Hình không mô tả API ghi phím, cài đặt ẩn hoặc gửi dữ liệu thu thập. Nó chỉ phân biệt các điểm dữ liệu tồn tại trong hệ thống.',
 ['TLS không mã hóa tín hiệu từ bàn phím đến hệ điều hành.','Không phải mọi rủi ro ghi phím đều có cùng cơ chế hoặc cùng khả năng phát hiện.'],
 'Nếu mục tiêu là bảo vệ đoạn bàn phím → ứng dụng, chỉ bật HTTPS có đủ không?','Không. Cần bảo vệ thiết bị và đầu cuối, vì đoạn đó diễn ra trước phạm vi bảo vệ của TLS.')
M('virus-worm','2b','2b.1.1','Virus và worm: hai nhánh lan truyền khác nhau','Hai nhánh có chung hậu quả nhưng khác cách tạo bản sao và điều kiện kích hoạt.',[
 N('host','a','Đối tượng chủ','Nhánh virus','File hoặc đối tượng phù hợp mang phần mã virus; không đồng nhất với khái niệm máy chủ mạng.'),N('run','b','Chủ được thực thi','Nhận điều khiển','Một cơ chế kích hoạt đưa điều khiển đến mã virus trong mô hình đang xét.'),N('copy','c','Đối tượng chủ khác','Lây thêm','Virus tìm đối tượng có thể lây và gắn mã theo cơ chế của nó.'),N('worm','d','Chương trình worm','Nhánh độc lập','Worm có khả năng tự lan sang hệ thống khác mà không cần gắn vào chương trình chủ theo định nghĩa virus.'),N('network','e','Đường lan phù hợp','Mạng / dịch vụ','Việc lan truyền cần đường tiếp cận và điều kiện mà mẫu worm khai thác hoặc lợi dụng.'),N('machine','f','Máy khác','Bản sao mới','Một bản sao được thực thi trên máy khác khi điều kiện lây nhiễm được đáp ứng.')],
 [E('a','host','run','1'),E('b','run','copy','2'),E('c','worm','network','3'),E('d','network','machine','4')],[
 S('Virus cần mối liên hệ với đối tượng chủ','Virus có cơ chế gắn vào đối tượng chủ để được kích hoạt cùng một sự kiện thích hợp. Từ “host” ở đây nói về vật mang mã, không bắt buộc là server cung cấp dịch vụ. Chỉ có một file độc hại chưa đủ chứng minh nó là virus.','a'),
 S('Khi chạy, virus có thể lây sang đối tượng khác','Sau khi nhận điều khiển, mã tìm đối tượng phù hợp rồi tạo sự lây nhiễm mới. Việc phá hoại và việc lây là hai chức năng khác nhau: có mẫu chưa biểu hiện phá hoại rõ nhưng vẫn có cơ chế lây. Không mô tả mọi mẫu là có cùng thứ tự nội bộ.','b'),
 S('Worm có chương trình lan truyền độc lập','Worm không cần gắn vào file chủ theo cách định nghĩa virus. Tuy vậy, “tự lan” không có nghĩa vượt qua mọi mạng hoặc mọi máy: còn phụ thuộc dịch vụ, cấu hình, quyền và cơ chế mà mẫu đó sử dụng.','c'),
 S('Chọn điểm cắt theo đường lan','Kiểm soát file và thực thi giúp với nhánh virus; vá lỗi, phân đoạn mạng và giới hạn dịch vụ có thể cắt nhánh worm. Thực tế một họ malware có thể kết hợp nhiều khả năng, nên phân loại là công cụ hiểu cơ chế chứ không thay điều tra hành vi.','d')],
 'Một tài liệu mang mã lây khi người dùng mở khác với một chương trình lan qua dịch vụ mạng. Cả hai vẫn có thể làm gián đoạn máy hoặc ảnh hưởng dữ liệu.',
 'Hai nhánh là mô hình phân biệt, không phải danh mục đầy đủ mọi cách lan hoặc mọi loại malware lai.',
 ['“Có hại” không tự đồng nghĩa “virus”.','Zombie mô tả trạng thái máy bị điều khiển, không phải cơ chế lây của virus.'],
 'Tại sao chặn chia sẻ file chưa chắc chặn mọi worm?','Vì đường lan có thể là dịch vụ/cơ chế khác; phải xác định điều kiện và đường tiếp cận cụ thể.')
M('detection','2b','2b.4.2','Ba cách phát hiện: nhận dạng, nghi vấn và so sánh','Ba nhánh trả lời ba câu hỏi khác nhau; phối hợp chúng tốt hơn đánh đồng chúng.',[
 N('object','b','File / hành vi','Đối tượng kiểm tra','Đầu vào có thể gồm nội dung file, thuộc tính hoặc hành vi được quan sát.'),N('signature','d','Signature','Có khớp mẫu?','Mẫu nhận dạng mô tả đặc điểm đã biết để tìm dấu vết phù hợp.'),N('heuristic','e','Heuristic','Có đáng ngờ?','Quy tắc hoặc mô hình suy luận từ đặc điểm, cấu trúc và hành vi.'),N('baseline','f','Integrity check','Có thay đổi?','Giá trị kiểm tra hiện tại được so với baseline tin cậy.'),N('decision','h','Đánh giá bối cảnh','Không kết luận máy móc','Kết quả được ghép với nguồn file, cập nhật, quyền, log và tác động thực tế.')],
 [E('a','object','signature','1'),E('b','object','heuristic','2'),E('c','object','baseline','3'),E('d','signature','decision','4'),E('e','heuristic','decision','4'),E('f','baseline','decision','4')],[
 S('Đối chiếu mẫu đã biết','Signature phù hợp với đặc điểm đã được mô tả trong bộ nhận dạng. Nó có thể hoạt động nhanh và chính xác trong phạm vi mẫu; thiếu kết quả khớp không chứng minh an toàn, vì mẫu có thể mới hoặc đã biến đổi.','a'),
 S('Tìm dấu hiệu đáng nghi','Heuristic dùng quy tắc/đặc trưng để nghi ngờ trường hợp chưa có mẫu chính xác. Phạm vi suy luận rộng hơn nhưng có thể đánh nhầm ứng dụng hợp lệ. Cần phân biệt một cảnh báo với một kết luận đã xác minh.','b'),
 S('Đối chiếu tính toàn vẹn','Integrity Check Value (ICV) trong bối cảnh giám sát file được so với bản chuẩn. Khác giá trị cho biết file khác baseline theo phép kiểm, không tự chỉ ra nguyên nhân. Nếu baseline ban đầu đã nhiễm, so sánh với nó cũng không tạo được sự tin cậy.','c'),
 S('Ghép bằng chứng trước khi xử lý','Một bản cập nhật hợp lệ có thể làm hash thay đổi. Ngược lại, file giữ nguyên kích thước vẫn có thể thay nội dung. Quyết định cần bối cảnh nguồn phát hành, sự kiện cập nhật và các dấu hiệu khác; không chỉ nhìn một con số.',['d','e','f'])],
 'Sau khi cập nhật phần mềm chính thức, hash khác baseline cũ là điều có thể dự đoán. Hãy xác minh nguồn và bản cập nhật, rồi cập nhật baseline theo quy trình, thay vì mặc định xóa file.',
 'Mô hình so sánh nguyên tắc, không mô phỏng độ chính xác của một antivirus hoặc mọi kỹ thuật phân tích.',
 ['ICV thay đổi không đồng nghĩa chắc chắn có virus.','Heuristic không phải phép chứng minh tuyệt đối.'],
 'Hash không đổi so với một baseline bị nhiễm có chứng minh file sạch không?','Không. Tính tin cậy của baseline là điều kiện nền tảng của phép so sánh.')
M('symmetric','3','3.4.1','Mã hóa đối xứng: cùng bí mật, hai chiều xử lý','Phân biệt bản rõ, thuật toán, khóa và bản mã; khóa không đi kèm công khai với bản mã.',[
 N('m','a','Bản rõ m','Dữ liệu cần bảo vệ','Thông điệp trước mã hóa; phải được biểu diễn thành chuỗi bit/byte phù hợp.'),N('enc','b','Mã hóa E','Dùng khóa K','Phép mã hóa phụ thuộc thuật toán, khóa và các tham số như nonce/IV theo chế độ.'),N('cipher','c','Bản mã c','Đi qua kênh','Dữ liệu được biến đổi để người không có khóa khó suy ra bản rõ trong mô hình an toàn.'),N('dec','f','Giải mã D','Dùng khóa tương ứng','Đầu nhận có bí mật đối xứng phù hợp để khôi phục thông điệp.'),N('out','e','Bản rõ m','Kết quả khôi phục','Thông điệp sau giải mã còn phải được xử lý theo cơ chế kiểm tra toàn vẹn/xác thực được dùng.')],
 [E('a','m','enc','1 · m'),E('b','enc','cipher','2 · c'),E('c','cipher','dec','3 · c'),E('d','dec','out','4 · m')],[
 S('Hai bên phải có khóa theo cách an toàn','K là tham số bí mật, khác với tên thuật toán. Biết thuật toán không được xem là biết khóa. Bài toán phân phối/thiết lập khóa tồn tại trước hoặc trong giao thức; chỉ gửi khóa cùng bản mã qua cùng kênh không bảo vệ thì mất ý nghĩa bí mật.','a'),
 S('Mã hóa phụ thuộc cả chế độ sử dụng','Viết gọn c=E(K,m) giúp hiểu nguyên tắc. Một phép triển khai còn cần encoding, chia khối và tham số của mode. IV/nonce không nhất thiết bí mật nhưng phải đáp ứng điều kiện của mode; tái sử dụng sai có thể làm lộ quan hệ giữa các thông điệp.','b'),
 S('Người nhận dùng đúng khóa và tham số','Đầu nhận lấy c và các tham số cần thiết, áp dụng D để phục hồi m. Bản mã có thể bị thay, gửi thiếu hoặc phát lại; việc nhìn nó “không đọc được” chưa chứng minh nó chưa bị can thiệp.','c'),
 S('Khôi phục không đồng nghĩa đã xác thực','Mã hóa thuần túy không tự bảo đảm toàn vẹn. Một thiết kế có xác thực dùng tag và từ chối dữ liệu không hợp lệ trước khi sử dụng kết quả theo quy tắc của nó. Chống replay cần cơ chế tính mới bổ sung phù hợp.','d')],
 'Alice và Bob đã có K. Alice mã hóa tài liệu, Bob giải mã bằng K tương ứng. Nếu người khác lấy được K, bảo mật của các dữ liệu chịu ảnh hưởng của khóa đó có thể mất dù thuật toán không đổi.',
 'Hình bỏ qua mode cụ thể và quản lý khóa chi tiết; không phải mọi hệ đối xứng đều có cấu trúc nội bộ giống nhau.',
 ['Độ dài khối khác độ dài khóa.','Bí mật thuật toán không thay được bí mật khóa.'],
 'Tại sao AES mạnh nhưng dùng nonce sai vẫn có thể nguy hiểm?','Độ an toàn phụ thuộc cả thuật toán lẫn cách sử dụng mode và tham số; không chỉ phụ thuộc tên AES.')
M('feistel','3','3.4.2','Một vòng Feistel của DES: đổi chỗ và XOR','Theo dõi đúng hai nửa dữ liệu thay vì học thuộc tên các phép biến đổi.',[
 N('left','a','Lᵢ₋₁','Nửa trái · 32 bit','Nửa trái của khối 64 bit trước vòng đang xét.'),N('right','b','Rᵢ₋₁','Nửa phải · 32 bit','Nửa phải đồng thời đi vào F và trở thành nửa trái vòng sau.'),N('fun','e','F(R, Kᵢ)','Khóa con 48 bit','Hàm vòng DES: mở rộng 32→48 bit, XOR khóa con, S-box 48→32 bit rồi hoán vị P.'),N('nextleft','c','Lᵢ = Rᵢ₋₁','Chuyển sang trái','Một nhánh được chuyển nguyên vẹn sang nửa trái vòng kế tiếp.'),N('xor','d','Rᵢ = Lᵢ₋₁ ⊕ F','Nửa phải mới','XOR hai giá trị 32 bit tạo nửa phải sau vòng; ⊕ là XOR theo từng bit.')],
 [E('a','right','nextleft','1'),E('b','right','fun','2'),E('c','left','xor','3 · L'),E('d','fun','xor','3 · XOR')],[
 S('Tách và đặt tên theo vòng','DES xử lý khối 64 bit. Ở vòng i, đầu vào là hai nửa Lᵢ₋₁ và Rᵢ₋₁, mỗi nửa 32 bit. Chỉ số là số vòng, không phải số bit. Tách tên rõ giúp tránh nhầm bên nào đi vào F.','a'),
 S('Hàm F trộn nửa phải với khóa vòng','DES mở rộng R từ 32 lên 48 bit, XOR với Kᵢ 48 bit. Tám S-box nhận tổng 48 bit và trả tổng 32 bit; sau đó P hoán vị các bit. S-box tạo phi tuyến, còn hoán vị giúp phân tán ảnh hưởng qua các vòng.','b'),
 S('Tạo hai nửa mới','Lᵢ=Rᵢ₋₁; Rᵢ=Lᵢ₋₁⊕F(Rᵢ₋₁,Kᵢ). Không phải cả hai nửa đều độc lập chạy qua F. Nửa phải cũ có hai vai trò: chuyển sang trái và cung cấp đầu vào cho F.',['c','d']),
 S('Vì sao đảo được dù F không cần đảo được?','Khi biết Lᵢ,Rᵢ, suy ra Rᵢ₋₁=Lᵢ và Lᵢ₋₁=Rᵢ⊕F(Lᵢ,Kᵢ). Vì x⊕y⊕y=x, có thể khôi phục nửa cũ. Trong mạng Feistel, dùng khóa vòng theo thứ tự ngược giúp giải mã; vẫn cần đúng các hoán vị/đổi chỗ của toàn bộ DES.',['a','b','c','d'])],
 'Ví dụ XOR đơn giản: 1010⊕0110=1100; 1100⊕0110=1010. Đây chỉ minh họa tính tự đảo của XOR, không thay F hoặc mô phỏng đầy đủ một vòng DES.',
 'Hình là một vòng, bỏ qua IP, FP, lịch khóa và cách ghép cuối. DES có 16 vòng, khóa hiệu dụng 56 bit; đây là nội dung lịch sử, không phải khuyến nghị dùng DES mới.',
 ['S-box làm thay đổi giá trị, không chỉ đổi vị trí.','F không cần khả nghịch để mạng Feistel khả nghịch.'],
 'Biết Lᵢ,Rᵢ và Kᵢ, tại sao không cần tính F nghịch đảo?','Vì tính lại F với nửa phải cũ đã suy ra, sau đó dùng XOR để lấy lại nửa trái cũ.')
M('aes','3','3.4.3','AES-128: khối dữ liệu đi qua các vòng như thế nào?','Đi từ state 4×4 byte đến bốn phép biến đổi; phân biệt một vòng với toàn bộ phép mã hóa.',[
 N('state','a','State 4 × 4 byte','Khối 128 bit','16 byte được sắp thành state theo quy ước AES; không phải bốn khối độc lập.'),N('key','b','AddRoundKey','XOR khóa vòng','XOR state với một khóa vòng 128 bit sinh từ lịch khóa.'),N('sub','c','SubBytes','Thay từng byte','Áp dụng cùng S-box khả nghịch lên mỗi byte để tạo phi tuyến.'),N('shift','f','ShiftRows','Dịch theo hàng','Các hàng dịch vòng khác độ lệch, làm byte chuyển sang cột khác.'),N('mix','e','MixColumns','Trộn từng cột','Biến đổi tuyến tính khả nghịch trên GF(2⁸) để mỗi byte đầu ra phụ thuộc nhiều byte trong cột.'),N('end','d','AddRoundKey','Kết thúc vòng','Khóa vòng tiếp theo được XOR vào state đã biến đổi.')],
 [E('a','state','key','0 · ban đầu'),E('b','key','sub','1'),E('c','sub','shift','2'),E('d','shift','mix','3'),E('e','mix','end','4')],[
 S('Nạp khối và cộng khóa ban đầu','AES-128 nhận khối 128 bit, xếp thành state 16 byte và thực hiện AddRoundKey đầu tiên. Khóa vòng là 128 bit; một word 32 bit chỉ là thành phần của khóa vòng. Dữ liệu dài hơn cần chế độ mã hóa phù hợp.','a'),
 S('SubBytes thay giá trị từng byte','Mỗi byte đi qua S-box. Đây không phải đổi thứ tự byte: giá trị byte thay theo bảng/ánh xạ xác định và khả nghịch. Tính phi tuyến giúp phá vỡ các quan hệ tuyến tính đơn giản giữa đầu vào, khóa và đầu ra.','b'),
 S('ShiftRows chuyển vị trí','Hàng 0 giữ nguyên; các hàng 1,2,3 dịch vòng lần lượt 1,2,3 vị trí trong chiều mã hóa. Nó chưa trộn số học các byte, nhưng đưa các byte của một cột sang các cột khác, chuẩn bị cho khuếch tán qua MixColumns.','c'),
 S('MixColumns lan ảnh hưởng trong cột','Mỗi cột được nhân với ma trận cố định trong trường hữu hạn GF(2⁸). Phép cộng là XOR, phép nhân không phải nhân số nguyên thông thường. Sau nhiều vòng, kết hợp ShiftRows và MixColumns giúp thay đổi một byte ảnh hưởng rộng hơn trong state.','d'),
 S('Cộng khóa vòng và lặp có ngoại lệ','Một vòng thường kết thúc bằng AddRoundKey. AES-128 có 10 vòng sau phép cộng khóa ban đầu; vòng cuối bỏ MixColumns. Vì vậy có 11 khóa vòng. AES-192/256 vẫn có khối 128 bit nhưng có 12/14 vòng và số khóa vòng khác.','e')],
 'Hãy đánh dấu một byte bằng màu tưởng tượng: SubBytes đổi giá trị; ShiftRows đổi vị trí; MixColumns lan ảnh hưởng sang các byte cùng cột; AddRoundKey đưa ảnh hưởng của khóa vòng vào. Đây là cách kể cơ chế, không phải tính ciphertext cụ thể.',
 'Hình tách các phép để dễ nhìn; hai hộp AddRoundKey là hai thời điểm khác nhau. Không lặp phép cộng khóa ban đầu trước mọi vòng. Vòng cuối không có MixColumns.',
 ['128 bit là độ dài khối của mọi biến thể AES.','11 khóa vòng chỉ đúng AES-128.','MixColumns dùng số học trường hữu hạn.'],
 'Tại sao nói “AES có 10 vòng” mà không nêu biến thể là thiếu chính xác?','Vì chỉ AES-128 có 10 vòng; AES-192 và AES-256 lần lượt có 12 và 14 vòng.',
 ['https://csrc.nist.gov/pubs/fips/197/final'])
M('rsa','4','4.4.1','RSA: tạo khóa, mã hóa và giải mã một số nhỏ','Đi một ví dụ tính tay trọn vẹn để hiểu vai trò từng đại lượng; không dùng tham số nhỏ cho bảo mật thực tế.',[
 N('primes','a','p = 5, q = 11','Hai số nguyên tố','Hai số nguyên tố khác nhau được chọn để minh họa tạo khóa.'),N('params','b','n = 55, φ = 40','Môđun & Euler phi','n=pq; với p,q nguyên tố khác nhau, φ(n)=(p−1)(q−1).'),N('keys','c','e = 3, d = 27','ed ≡ 1 (mod 40)','Public key=(e,n); private exponent d và thông tin khóa riêng phải giữ bí mật.'),N('encrypt','f','m = 7 → c = 13','c = mᵉ mod n','Bản rõ được mã hóa thành số nguyên trong khoảng 0≤m<n theo mô hình RSA trần.'),N('decrypt','e','c = 13 → m = 7','m = cᵈ mod n','Giải mã dùng d tương ứng để phục hồi đại diện số của thông điệp.')],
 [E('a','primes','params','1'),E('b','params','keys','2'),E('c','keys','encrypt','3'),E('d','encrypt','decrypt','4')],[
 S('Tạo môđun và giá trị phục vụ tìm khóa','Chọn p=5,q=11 nên n=55, φ(n)=4×10=40. Các số này không có đơn vị vật lý. n được công khai; việc giữ bí mật p,q quan trọng vì phân tích được n sẽ giúp xây dựng lại thông tin giải mã trong mô hình này.','a'),
 S('Chọn e và tìm d bằng nghịch đảo môđun','e=3 nguyên tố cùng nhau với 40. Chọn d=27 vì 3×27=81=2×40+1. d không bằng 1/e theo số thực; nó là nghịch đảo nhân trong phép tính modulo. Ví dụ dùng điều kiện theo φ(n) như trong bài nhập môn.','b'),
 S('Mã hóa với public key của người nhận','m=7 nằm trong 0..54. c=7³ mod55=343 mod55=13. Bất kỳ ai biết public key đều có thể mã hóa một đại diện số cho chủ khóa; điều đó không tự chứng minh danh tính người gửi.','c'),
 S('Giải mã bằng d và kiểm tra phép tính','13² mod55=4; 13⁴ mod55=16; 13⁸ mod55=36; 13¹⁶ mod55=31. Vì 27=16+8+2+1, lấy 31×36×4×13 mod55 được 7. Bình phương–nhân giúp không cần tạo số nguyên khổng lồ trước khi lấy dư.','d')],
 'Chuỗi số đầy đủ: (5,11) → (55,40) → (e=3,d=27) → 7 → 13 → 7. Điểm cần tự giải thích là vì sao public key cho phép mã hóa nhưng không được kỳ vọng cho phép suy ra d hiệu quả với tham số đủ mạnh.',
 'RSA trần trong hình là bài toán học thuật. Hệ thống thực dùng encoding/padding và giao thức chuẩn, chẳng hạn RSA-OAEP cho mã hóa; không tự ghép RSA trần để bảo vệ dữ liệu. Chữ ký RSA cũng không đơn giản là “mã hóa ngược”.',
 ['d là nghịch đảo modulo, không là nghịch đảo số thực.','Chỉ bí mật khóa riêng; không cần bí mật public key.','Ví dụ nhỏ không có độ an toàn thực tế.'],
 'Nếu e=4 trong ví dụ φ(n)=40 thì có tìm d theo yêu cầu không?','Không. gcd(4,40)=4≠1 nên không có nghịch đảo nhân modulo 40.')
M('dh','4','4.3','Diffie–Hellman: không gửi bí mật vẫn cùng ra một khóa','Theo dõi hai phép tính gặp nhau ở g^(ab) mod p và điều kiện xác thực còn thiếu.',[
 N('public','b','p = 23, g = 5','Tham số công khai','p,g được công khai trong ví dụ nhóm nhỏ; hệ thực cần nhóm/tham số được lựa chọn phù hợp.'),N('alice','d','Alice: a = 6','A = 5⁶ mod23 = 8','a là bí mật cục bộ của Alice; A là giá trị công khai được trao đổi.'),N('bob','f','Bob: b = 15','B = 5¹⁵ mod23 = 19','b là bí mật cục bộ của Bob; B là giá trị công khai được trao đổi.'),N('ka','g','Alice tính Bᵃ','19⁶ mod23 = 2','Alice dùng giá trị công khai Bob gửi và bí mật riêng a.'),N('kb','i','Bob tính Aᵇ','8¹⁵ mod23 = 2','Bob dùng giá trị công khai Alice gửi và bí mật riêng b.')],
 [E('a','public','alice','1'),E('b','public','bob','1'),E('c','alice','bob','2 · A=8'),E('d','bob','alice','2 · B=19'),E('e','alice','ka','3'),E('f','bob','kb','3')],[
 S('Hai bên thống nhất nhóm công khai','Alice và Bob biết p=23,g=5. Không coi những giá trị này là mật khẩu. Đối phương nghe được p,g,A,B vẫn phải giải bài toán khó tương ứng để suy ra bí mật trong một nhóm đủ mạnh; ví dụ nhỏ ở đây chỉ phục vụ tính tay.',['a','b']),
 S('Chỉ trao đổi kết quả lũy thừa','Alice giữ a=6, gửi A=8; Bob giữ b=15, gửi B=19. a và b không được gửi cho nhau. Cần phân biệt chữ hoa giá trị công khai với chữ thường bí mật để không nhầm thứ phải bảo vệ.',['c','d']),
 S('Hai đường tính đến cùng bí mật','Alice tính Bᵃ=(gᵇ)ᵃ; Bob tính Aᵇ=(gᵃ)ᵇ. Cả hai bằng g^(ab) trong nhóm. Ở ví dụ này đều bằng 2. Hệ thực đưa bí mật chia sẻ qua hàm dẫn xuất khóa, không xem ngay số nhỏ thô là khóa AES hợp lệ.',['e','f']),
 S('Cùng ra số chưa chứng minh đúng người','DH thuần túy không xác thực người gửi A,B. Nếu giá trị công khai bị thay, hai bên có thể thiết lập bí mật với một trung gian thay vì với nhau. Giao thức cần ràng buộc trao đổi với danh tính bằng chữ ký/chứng chỉ hoặc bí mật có trước phù hợp.',['c','d'])],
 'Tự bấm máy: 5⁶ mod23=8, 5¹⁵ mod23=19, 19⁶ mod23=2 và 8¹⁵ mod23=2. Không có bước nào phải truyền a=6 hoặc b=15.',
 'Tham số rất nhỏ, không dùng triển khai. Hình lược bỏ kiểm tra giá trị công khai, lựa chọn nhóm, KDF và cơ chế xác thực của giao thức bao ngoài.',
 ['Trao đổi khóa không đồng nghĩa mã hóa thông điệp.','Không gửi khóa không có nghĩa tự chống MITM.'],
 'Người nghe trộm biết A và B có phải đã biết a và b không?','Không. Đảo từ giá trị công khai về số mũ là bài toán khác; với nhóm đủ mạnh được giả định khó, nhưng nhóm nhỏ minh họa này không an toàn.')
M('hash','5','5.3.1','Hàm băm: kiểm tra dấu vết, không phải giải mã','Nhìn rõ phép so sánh hai digest và điều kiện nguồn digest phải đáng tin.',[
 N('original','a','File gốc m','Độ dài bất kỳ','Đầu vào là chuỗi byte; thay encoding cũng có thể làm byte thay đổi.'),N('hash1','b','H(m)','Digest n bit','Hàm băm mật mã ánh xạ đầu vào thành đầu ra cố định với thuật toán đã chọn.'),N('trusted','c','Digest chuẩn','Kênh tin cậy','Giá trị đối chiếu cần được xác thực hoặc nhận từ nguồn đáng tin.'),N('received','d','File nhận m′','Có thể đã khác','File cần được kiểm tra sau tải hoặc sau lưu trữ.'),N('hash2','e','H(m′)','Cùng thuật toán','Tính lại từ chính byte nhận, không so tên file hoặc chỉ so kích thước.'),N('compare','f','So sánh digest','Bằng / khác','Kết quả cần diễn giải theo tính chất và độ an toàn của hàm băm.')],
 [E('a','original','hash1','1'),E('b','hash1','trusted','2'),E('c','received','hash2','3'),E('d','hash2','compare','4'),E('e','trusted','compare','4')],[
 S('Rút thông điệp thành digest','Hash không có khóa giải mã để lấy lại toàn bộ file. Do tập đầu vào lớn hơn tập đầu ra cố định, va chạm tồn tại về toán học. Mục tiêu an toàn là khiến việc tìm những va chạm/tiền ảnh phù hợp trở nên khó, không phải tuyên bố không thể có.','a'),
 S('Bảo vệ nguồn của dấu vết chuẩn','Nếu đối phương thay được cả file lẫn digest đăng cạnh file, họ có thể tính digest mới cho file đã sửa. Vì vậy “có hash trên trang” khác với “có digest chuẩn đã được xác thực”.','b'),
 S('Tính lại trên dữ liệu thực nhận','Dùng cùng thuật toán và cùng cách biểu diễn byte. Việc đổi xuống dòng hoặc encoding có thể làm hash khác dù nội dung nhìn tương tự. Hash kiểm tra byte, không hiểu ý nghĩa tài liệu.','c'),
 S('Diễn giải kết quả có điều kiện','Digest khác chứng minh hai chuỗi byte khác dưới phép tính đúng. Digest bằng không phải chứng minh tuyệt đối hai đầu vào giống nhau, vì va chạm có thể tồn tại; mức tin cậy phụ thuộc hàm băm và mô hình đối phương. Băm trần không tự xác thực người gửi.',['d','e'])],
 'Tải một bản cài và so SHA-256 với digest lấy qua nguồn đã xác thực giúp kiểm tra file. Nếu chỉ lấy file và digest từ cùng một nguồn đã bị thay, phép so sánh có thể vẫn đạt.',
 'Hình mô tả băm mật mã, không đồng nhất với XOR-hash minh họa hoặc checksum chống lỗi ngẫu nhiên.',
 ['Hash không phải mã hóa một chiều có thể giải bằng khóa.','Digest bằng không tự chứng minh nguồn gốc.'],
 'Vì sao đặt digest cạnh file chưa đủ chống người sửa được cả hai?','Vì hàm băm công khai: đối phương cũng tính được digest của file thay thế.')
M('mac','5','5.2.1','MAC/HMAC: người biết khóa tạo và kiểm tag','Khác biệt quyết định với hash trần là bí mật chia sẻ K.',[
 N('send','a','Alice: m, K','Tạo thông điệp','Alice và Bob đã có cùng khóa bí mật K.'),N('tag','b','T = MAC(K,m)','Tag xác thực','Với HMAC, cấu trúc hash có khóa tạo tag; không phải thêm checksum vào hash.'),N('channel','c','Gửi m và T','K không gửi kèm','Thông điệp có thể vẫn là bản rõ nếu không có lớp mã hóa riêng.'),N('verify','f','Bob tính T′','T′ = MAC(K,m nhận)','Bob dùng cùng khóa và thuật toán để tính lại tag trên dữ liệu thực nhận.'),N('decision','e','So sánh T và T′','Chấp nhận / loại','Chỉ sử dụng nội dung khi thỏa toàn bộ kiểm tra giao thức, gồm tính mới nếu cần.')],
 [E('a','send','tag','1'),E('b','tag','channel','2'),E('c','channel','verify','3'),E('d','verify','decision','4')],[
 S('Khóa tạo sự khác biệt với hash công khai','Người không có K không được kỳ vọng tạo tag hợp lệ cho thông điệp giả mạo trong điều kiện an toàn. Tuy nhiên cả Alice lẫn Bob đều biết K, nên cả hai đều có khả năng tạo tag. Điều này quan trọng khi hỏi về chống chối bỏ.','a'),
 S('Tag đi cùng thông điệp, không che nội dung','Gửi m,T là đủ để đầu nhận kiểm MAC; K phải được giữ bí mật qua cơ chế khác. Ai quan sát kênh vẫn có thể đọc m nếu nó không được mã hóa. Tính xác thực/toàn vẹn và tính bí mật là những mục tiêu khác nhau.','b'),
 S('Tính lại trên thông điệp nhận','Nếu dữ liệu đổi thành m′, Bob tính MAC(K,m′), không tính lại trên bản m cũ tưởng rằng đã nhận. Một thay đổi thông thường sẽ làm tag kiểm tra không khớp. Tag đủ dài và khóa phù hợp hạn chế khả năng đoán giả mạo; không nói xác suất bằng 0.','c'),
 S('MAC đúng còn cần bối cảnh và tính mới','Thông điệp cũ có tag đúng có thể bị phát lại. Giao thức phải xác thực cả trường liên quan như số thứ tự, định danh phiên, ngữ cảnh và kiểm tra chúng. MAC không chứng minh cho bên thứ ba rằng chỉ riêng Alice có thể tạo thông điệp đó.','d')],
 'Alice gửi “số tiền=100” và T. Nếu dữ liệu bị đổi thành “số tiền=900”, Bob phải tính tag từ chuỗi mới rồi so với T; chỉ đổi nội dung mà không biết K không đủ để tạo một thông điệp hợp lệ như người gửi.',
 'Đây là mô hình MAC chung. HMAC có cấu trúc lồng hash với ipad/opad, không tự đặt công thức H(K||m) thay HMAC. Hình không mô phỏng tính toán mật mã thực.',
 ['MAC không tự mã hóa m.','Khóa chung không tạo bằng chứng chống chối bỏ độc lập.'],
 'Vì sao Bob không dùng tag để chứng minh chỉ Alice đã tạo m cho một người thứ ba?','Vì chính Bob cũng biết K và có thể tạo một tag như vậy.', ['https://www.rfc-editor.org/info/rfc2104/'])
M('signature','5','5.4','Chữ ký số: ký bằng khóa riêng, kiểm bằng khóa công khai','Theo dõi cả thông điệp lẫn digest và điều kiện tin đúng public key.',[
 N('m','a','Thông điệp m','Nội dung cần ký','Thông điệp được biểu diễn thành byte theo quy tắc của định dạng/giao thức.'),N('sign','b','Ký với private key','Tạo chữ ký σ','Thuật toán ký chuẩn xử lý thông điệp/digest cùng khóa riêng; một số thuật toán cần ngẫu nhiên hoặc nonce đúng quy tắc.'),N('wire','c','m và σ','Gửi người kiểm','Thông điệp không nhất thiết bí mật vì có chữ ký.'),N('key','d','Public key đã tin','Gắn với danh tính','Cần xác minh quan hệ giữa danh tính người ký và khóa dùng để kiểm.'),N('verify','f','Verify(pk,m,σ)','Hợp lệ / không','Thuật toán kiểm tra ràng buộc chữ ký với thông điệp và public key tương ứng.')],
 [E('a','m','sign','1'),E('b','sign','wire','2'),E('c','wire','verify','3'),E('d','key','verify','4')],[
 S('Khóa riêng tạo chữ ký','Người ký giữ private key và dùng thuật toán chữ ký phù hợp. Hash thường tham gia để ràng buộc nội dung vào chữ ký, nhưng chi tiết tùy thuật toán. Không định nghĩa mọi chữ ký là “mã hóa digest bằng khóa riêng”: đó là lối ví von không đúng tổng quát.','a'),
 S('Thông điệp và chữ ký là hai dữ liệu liên quan','Người nhận cần đúng nội dung đã ký để kiểm tra. Chữ ký không làm người ngoài mất khả năng đọc m. Muốn bí mật, còn cần cơ chế mã hóa phù hợp; ký và mã hóa giải quyết các yêu cầu khác nhau.','b'),
 S('Kiểm tra trên nội dung hiện có','Người kiểm chạy Verify với m,σ và public key. Nếu nội dung bị sửa, chữ ký cũ thường không còn hợp lệ cho nội dung mới. Kết quả không hợp lệ có thể do nhiều nguyên nhân: sửa dữ liệu, sai khóa, sai định dạng hoặc chữ ký không đúng.','c'),
 S('Xác minh đúng chủ thể của public key','Một chữ ký hợp lệ với khóa do đối phương tự cung cấp chỉ chứng minh quan hệ toán học với khóa đó. Cần chuỗi chứng chỉ/nguồn tin khóa và chính sách phù hợp để gắn nó với người mong đợi. Khả năng chống chối bỏ còn phụ thuộc quản lý khóa, thời điểm và bằng chứng liên quan.','d')],
 'Bạn nhận hợp đồng và chữ ký. Kiểm tra chữ ký bằng public key lấy từ nguồn đáng tin; nếu dùng khóa công khai được đính kèm nhưng chưa kiểm chứng danh tính, bạn có thể đang xác nhận chữ ký của người khác.',
 'Hình là luồng khái niệm, không thay quy tắc ký số của RSA-PSS, ECDSA hoặc thuật toán cụ thể; cũng không tự kết luận giá trị pháp lý.',
 ['Public key dùng kiểm chữ ký, không phải bí mật được chia sẻ.','Chữ ký hợp lệ không đồng nghĩa nội dung là đúng sự thật.'],
 'Một tài liệu nói sai sự thật nhưng được chính người viết ký thì chữ ký có thể hợp lệ không?','Có. Chữ ký ràng buộc nội dung với khóa ký; nó không kiểm chứng chân lý của nội dung.')
M('pki','6','6.2','PKI: vì sao bạn tin một public key thuộc đúng máy chủ?','Đi từ cấp chứng chỉ đến kiểm tra đường tin cậy; chữ ký CA chỉ là một trong các điều kiện.',[
 N('subject','a','Chủ thể','Giữ private key','Chủ thể sở hữu cặp khóa; yêu cầu chứng chỉ chứa public key và thông tin cần xác minh.'),N('ra','b','RA / xác minh','Kiểm tra yêu cầu','Registration Authority hoặc quy trình CA kiểm tra danh tính/quyền kiểm soát theo chính sách cấp.'),N('ca','c','CA','Ký chứng chỉ','Certification Authority ký cấu trúc ràng buộc thông tin chủ thể với public key.'),N('cert','f','Chứng chỉ X.509','Khóa + thông tin + ký','Chứng chỉ có tên, thời hạn, mục đích sử dụng và các trường cần kiểm tra, không chứa private key của chủ thể.'),N('client','e','Bên kiểm tra','Trust anchor cục bộ','Bên kiểm cần điểm tin cậy và quy tắc kiểm chuỗi, không tự tin mọi CA bất kỳ.')],
 [E('a','subject','ra','1'),E('b','ra','ca','2'),E('c','ca','cert','3'),E('d','cert','client','4')],[
 S('Yêu cầu cấp không phải tự chứng minh danh tính','Chủ thể tạo hoặc quản lý cặp khóa và đề nghị CA xác nhận public key. Việc có một cặp khóa mới chỉ chứng minh có khả năng mật mã tương ứng; còn cần chứng minh danh tính hoặc quyền kiểm soát tên theo chính sách của CA.','a'),
 S('Xác minh trước khi ký','RA/quy trình CA kiểm tra thông tin mà CA dự định chứng nhận. Không suy ra mọi chứng chỉ đều xác minh cùng mức thông tin: xác minh quyền kiểm soát tên miền khác với xác minh toàn bộ uy tín, tính hợp pháp hoặc nội dung website.','b'),
 S('Chứng chỉ là bản ràng buộc được ký','CA ký cấu trúc chứa public key và thông tin liên quan. Chứng chỉ có thể công khai; private key của chủ thể không được gửi kèm trong chứng chỉ. Nếu CA trung gian được dùng, bên nhận còn cần xây dựng đường tới trust anchor mà mình tin.','c'),
 S('Bên dùng kiểm nhiều điều kiện','Kiểm chữ ký từng liên kết, ràng buộc CA, thời hạn, tên máy chủ, key usage/purpose và trạng thái thu hồi theo chính sách. Một chữ ký toán học hợp lệ nhưng sai hostname hoặc hết hạn vẫn không phải chứng chỉ phù hợp để chấp nhận kết nối đó.','d')],
 'Bạn vào portal.example và nhận chứng chỉ có tên khác. Dù chữ ký CA hợp lệ, kiểm tra tên vẫn phải thất bại cho kết nối này. Nếu private key bị lộ, chủ thể cần xử lý thu hồi/thay khóa và chứng chỉ theo quy trình.',
 'Sơ đồ gộp RA vào một khâu; một CA có thể tự làm việc xác minh. Chi tiết CRL/OCSP, trust store và lỗi mạng phụ thuộc chính sách bên dùng.',
 ['Chứng chỉ không chứa private key của website.','Chứng chỉ không chứng nhận mọi nội dung website là an toàn.'],
 'Tại sao chứng chỉ tự ký chưa tự tạo được niềm tin từ người lạ?','Vì chữ ký chỉ tự ràng buộc với chính khóa đó; người nhận vẫn cần một lý do độc lập để tin khóa và danh tính.')
M('ipsec','6','6.3','IPsec tunnel: gói bên trong được bọc bởi gói bên ngoài','Theo một gói từ chi nhánh A sang B và phân biệt dữ liệu gốc với header dùng định tuyến qua Internet.',[
 N('a','a','Máy tại LAN A','Gói IP gốc','Nguồn và đích bên trong thuộc hai mạng cần kết nối.'),N('ga','b','Gateway A','Chính sách IPsec','Gateway quyết định bypass, discard hoặc protect dựa chính sách.'),N('gb','c','Gateway B','Kiểm và tháo bọc','Gateway đối tác nhận gói IPsec, kiểm tính hợp lệ và chuyển gói bên trong.'),N('b','f','Máy tại LAN B','Nhận gói gốc','Đầu nhận cuối không nhất thiết tự chạy IPsec trong mô hình site-to-site này.'),N('ike','e','IKE & SA','Thỏa thuận bảo vệ','Internet Key Exchange thiết lập thông số/khóa; Security Association ghi trạng thái bảo vệ cho một chiều.')],
 [E('a','a','ga','1 · IP gốc'),E('b','ga','gb','2 · tunnel'),E('c','gb','b','3 · IP gốc'),E('d','ike','ga','4 · SA'),E('e','ike','gb','4 · SA')],[
 S('Chính sách chọn loại xử lý','Không phải mọi gói tự động được mã hóa vì gateway hỗ trợ IPsec. Bộ chính sách xác định lưu lượng nào bỏ qua, loại bỏ hoặc phải bảo vệ. Nếu cần bảo vệ, thông số của SA và định tuyến phải phù hợp với luồng.','a'),
 S('Tunnel thêm lớp địa chỉ ngoài','Gói IP gốc được giữ làm dữ liệu bên trong. Với ESP tunnel có mã hóa, nó được bảo vệ trong phần payload theo bộ thuật toán đã chọn; header IP mới chứa địa chỉ gateway để mạng trung gian định tuyến. Router Internet không cần đọc địa chỉ IP bên trong để chuyển lớp gói ngoài.','b'),
 S('Đầu kia kiểm trước khi sử dụng','Gateway B xác định SA, kiểm tính toàn vẹn/xác thực và chống replay theo cấu hình, giải mã khi có mã hóa, rồi kiểm chính sách cho gói bên trong. Gói không hợp lệ không được chuyển vào LAN chỉ vì nó có header trông giống IPsec.','c'),
 S('Phân biệt mặt điều khiển và dữ liệu','IKE thương lượng/xác thực và tạo trạng thái khóa; ESP/AH xử lý lưu lượng theo SA. Một SA IPsec là một chiều, nên liên lạc hai chiều cần các SA tương ứng. AH không cung cấp bí mật nội dung; ESP có dịch vụ theo cấu hình, không chỉ có duy nhất một cách dùng.',['d','e'])],
 'Gói trong: máy LAN A → máy LAN B. Gói ngoài: gateway A → gateway B. Đổi sang transport mode thì không bọc toàn bộ gói gốc theo cùng cách; vì vậy không dùng hình tunnel để mô tả cả hai mode.',
 'Hình chọn site-to-site ESP tunnel có mã hóa để minh họa. Không khẳng định mọi IPsec đều mã hóa mọi header, hay bảo vệ cả đoạn LAN trước và sau gateway.',
 ['Header ngoài còn cần cho định tuyến.','VPN tới gateway không tự bảo vệ dữ liệu trên mọi đoạn trong LAN.'],
 'Người quan sát Internet có thể thấy địa chỉ gateway dù payload được mã hóa không?','Có. Header ngoài phục vụ định tuyến vẫn lộ các thông tin tương ứng.', ['https://www.rfc-editor.org/info/rfc4301/'])
M('tls','6','6.4','TLS 1.3: thỏa thuận, xác thực, rồi bảo vệ dữ liệu','Mô hình một kết nối đầy đủ dùng chứng chỉ máy chủ và trao đổi khóa tạm thời; không trộn với sơ đồ SSL/RSA cũ.',[
 N('client','a','Client','ClientHello','Đầu khởi tạo đề xuất tham số, gửi giá trị trao đổi khóa công khai theo nhóm đã chọn.'),N('server','c','Server','ServerHello','Máy chủ chọn tham số tương thích và gửi phần trao đổi khóa của mình.'),N('verify','d','Client xác minh','Chứng chỉ & transcript','Client kiểm danh tính máy chủ, chữ ký ràng buộc handshake và thông điệp xác nhận.'),N('records','f','Kênh ứng dụng','Khóa lưu lượng','Hai phía dùng các khóa lưu lượng riêng cho từng chiều và AEAD để bảo vệ record.')],
 [E('a','client','server','1 · Hello'),E('b','server','client','2 · Hello'),E('c','server','verify','3 · xác thực'),E('d','verify','records','4 · dữ liệu')],[
 S('Đề xuất và chọn tham số','ClientHello gửi các khả năng mà client hỗ trợ và dữ liệu trao đổi khóa công khai. ServerHello chọn tổ hợp phù hợp, không phải tùy ý chọn một thuật toán client không biết. Trong mô hình trao đổi khóa tạm thời, hai bên tính bí mật chung cục bộ, không gửi private exponent.','a'),
 S('Dẫn xuất các khóa theo giai đoạn','Kết quả trao đổi khóa và thông tin handshake đi vào lịch dẫn xuất khóa. TLS 1.3 dùng khóa handshake trước khi chuyển sang khóa ứng dụng; không có một khóa duy nhất dùng bất biến cho mọi mục đích. Các thông điệp sau ServerHello được bảo vệ theo quy tắc giao thức.','b'),
 S('Kiểm đúng máy chủ và toàn bộ cuộc trao đổi','Client kiểm chứng chỉ, tên đích và các điều kiện PKI. CertificateVerify chứng minh sở hữu khóa riêng tương ứng và ràng buộc với transcript handshake; Finished xác nhận khóa và tính toàn vẹn transcript. Chỉ kiểm “chứng chỉ có chữ ký” mà bỏ các kiểm tra khác là thiếu.','c'),
 S('Trao đổi ứng dụng bằng khóa đối xứng','Sau các xác nhận bắt buộc, record ứng dụng được bảo vệ bằng AEAD, kết hợp bí mật và kiểm tra toàn vẹn với thông tin liên quan. Các khóa cho hai chiều khác nhau. TLS không tự kiểm chứng website có nội dung trung thực hoặc máy đầu cuối có sạch malware không.','d')],
 'Trình duyệt truy cập cổng học tập: đầu tiên thỏa thuận và xác thực, sau đó mới gửi dữ liệu ứng dụng trong kênh bảo vệ. Biểu tượng HTTPS không có nghĩa chủ website không lừa đảo.',
 'Chọn nhánh full handshake có chứng chỉ; chưa vẽ PSK, resumption, client authentication, HelloRetryRequest hoặc 0-RTT. Không áp thứ tự TLS 1.3 cho mọi phiên bản SSL/TLS trong slide.',
 ['TLS 1.3 không dùng mô hình gửi premaster secret bằng RSA tĩnh như một số sơ đồ TLS cũ.','Mã hóa kênh không thay xác minh danh tính endpoint.'],
 'Tại sao cần CertificateVerify ngoài việc gửi chứng chỉ?','Vì gửi chứng chỉ công khai chưa chứng minh bên đang handshake nắm private key tương ứng và đã ràng buộc nó với cuộc trao đổi này.', ['https://www.rfc-editor.org/info/rfc9846/'])
M('hybrid-mail','6','6.5','Email mã hóa lai: dữ liệu dùng khóa phiên, khóa phiên dùng public key','Giải thích vì sao ghép hai loại mật mã thay vì mã hóa mọi byte bằng RSA.',[
 N('mail','a','Nội dung email','Thông điệp dài','Nội dung và tệp đính kèm cần bảo vệ trước khi vận chuyển/lưu ở các máy trung gian.'),N('session','b','Khóa phiên K','Sinh cho thông điệp','Khóa ngẫu nhiên đối xứng được dùng trong cơ chế mã hóa nội dung.'),N('content','c','Bản mã nội dung','Mã hóa đối xứng','Phần dữ liệu lớn được bảo vệ bằng thuật toán/chế độ nội dung phù hợp.'),N('wrap','e','Bảo vệ K','Public key của Bob','Một cơ chế bất đối xứng/hybrid chuẩn bảo vệ khóa nội dung cho người nhận.'),N('package','f','Gói gửi','Bản mã + khóa bảo vệ','Gói chứa dữ liệu đã mã hóa cùng thông tin cho người nhận lấy lại khóa.'),N('bob','i','Bob mở gói','Private key → K → m','Khóa riêng cho phép lấy lại khóa nội dung rồi giải mã thông điệp theo định dạng.')],
 [E('a','mail','session','1'),E('b','session','content','2'),E('c','session','wrap','3'),E('d','content','package','4'),E('e','wrap','package','4'),E('f','package','bob','5')],[
 S('Tạo khóa nội dung','Chọn khóa đối xứng K phù hợp và các tham số theo cơ chế đã chọn. “Khóa phiên” trong hình nói khóa nội dung của gói minh họa, không khẳng định mọi định dạng email dùng cùng một cấu trúc khóa.','a'),
 S('Mã hóa phần lớn dữ liệu bằng đối xứng','Mật mã đối xứng phù hợp xử lý khối lượng dữ liệu lớn. Cần mode/định dạng bảo vệ đúng; không chỉ thay tên thuật toán là đủ. Các dịch vụ toàn vẹn/xác thực phụ thuộc cơ chế được dùng.','b'),
 S('Bảo vệ khóa cho từng người nhận','Dùng khóa công khai đã xác minh của Bob để bảo vệ khả năng truy xuất K theo chuẩn. Với nhiều người nhận, gói có thể mang nhiều thông tin khóa riêng cho từng người thay vì mã hóa lại toàn bộ nội dung theo một public key duy nhất.','c'),
 S('Gửi gói và giải theo thứ tự ngược','Bob dùng khóa riêng để khôi phục khóa nội dung, rồi dùng khóa đó xử lý phần bản mã. Nếu khóa riêng không đúng người nhận hoặc thông tin khóa bị hỏng, việc biết ciphertext nội dung không đủ mở thư. Các kiểm tra tính hợp lệ của định dạng phải được thực hiện.',['d','e','f']),
 S('Ký số là một mục tiêu bổ sung','Mã hóa cho public key Bob không chứng minh Alice đã gửi: ai có public key Bob cũng có thể tạo thư mã hóa gửi Bob. Muốn xác thực người gửi cần chữ ký/cơ chế phù hợp và tin đúng khóa ký. Thứ tự ký, nén, đóng gói tùy PGP/S/MIME và phiên bản.','f')],
 'Một tệp lớn dùng một khóa nội dung; thông tin cho Bob lấy khóa có kích thước nhỏ hơn nhiều so với tệp. Bob cần khóa riêng của mình để lấy K, không cần private key của Alice để giải nội dung.',
 'Là mô hình mã hóa lai chung, không phải đặc tả byte hoặc thứ tự đầy đủ mọi phiên bản PGP/S/MIME. Không tự triển khai theo hình.',
 ['Public key người nhận phục vụ bí mật cho người nhận.','Private key người gửi phục vụ ký, không chia sẻ cho người nhận.'],
 'Thư chỉ được mã hóa cho Bob đã đủ chứng minh Alice viết thư chưa?','Chưa. Mã hóa cho Bob và xác thực Alice là hai yêu cầu khác nhau.')
M('kerberos','6','6.6','Kerberos: đổi vé thay vì gửi mật khẩu cho mọi dịch vụ','Theo ba cuộc trao đổi: AS, TGS và dịch vụ; phân biệt vé với authenticator.',[
 N('as','a','AS','Authentication Server','Thành phần KDC hỗ trợ bước xác thực ban đầu và cấp Ticket-Granting Ticket.'),N('tgs','c','TGS','Ticket-Granting Server','Thành phần KDC dùng TGT hợp lệ để cấp vé cho một dịch vụ cụ thể.'),N('client','d','Client','Giữ khóa phiên tạm','Client có cơ chế xác thực ban đầu, sau đó dùng vé và khóa phiên phù hợp.'),N('server','f','Dịch vụ SS','Kiểm vé dịch vụ','Application server có khóa dài hạn phù hợp để mở vé dành cho chính nó.')],
 [E('a','client','as','1 · AS-REQ'),E('b','as','client','2 · TGT'),E('c','client','tgs','3 · TGS-REQ'),E('d','tgs','client','4 · vé SS'),E('e','client','server','5 · AP-REQ'),E('f','server','client','6 · AP-REP')],[
 S('Xác thực ban đầu với AS','Client yêu cầu bước AS theo cơ chế Kerberos và pre-authentication được cấu hình. Không mô tả đây là gửi mật khẩu bản rõ trên mạng. AS cần có cách xác minh theo phương thức dùng trước khi cấp phản hồi phù hợp.','a'),
 S('Nhận TGT và khóa client–TGS','Phản hồi chứa TGT được bảo vệ cho TGS và phần cho client lấy khóa phiên client–TGS. Client không cần tự giải mã nội dung TGT để mang nó đi sử dụng. TGT là vé xin vé dịch vụ, chưa phải vé cho mọi ứng dụng tùy ý.','b'),
 S('Dùng TGT xin vé cho SS','Client gửi TGT, yêu cầu dịch vụ và authenticator bảo vệ bằng khóa phiên client–TGS. Authenticator chứng minh phía trình vé biết khóa phiên và cung cấp thông tin mới theo giao thức; chỉ sao chép vé không đồng nghĩa có đủ mọi điều kiện dùng vé.','c'),
 S('TGS trả vé và khóa client–SS','TGS kiểm yêu cầu rồi cấp vé dành cho SS, được bảo vệ bằng khóa mà SS có thể dùng để mở. Client nhận khóa phiên client–SS qua phần phản hồi được bảo vệ cho mình. Khóa này khác với khóa client–TGS.','d'),
 S('Trình vé dịch vụ và xác nhận hai chiều','Client gửi vé SS và authenticator tương ứng. SS kiểm vé, thời hạn, authenticator và replay theo quy tắc; nếu yêu cầu xác thực hai chiều, SS trả AP-REP chứng minh nắm khóa phiên. Đồng bộ thời gian, replay cache và bảo vệ khóa vẫn quan trọng.',['e','f'])],
 'Bạn đăng nhập một lần rồi mở dịch vụ được phép trong miền Kerberos. Dịch vụ nhận vé cho nó, không cần nhận mật khẩu của bạn mỗi lần. Có vé hợp lệ cũng chưa thay chính sách phân quyền của dịch vụ.',
 'AS và TGS thường là vai trò trong KDC, không bắt buộc hai máy vật lý. Hình mô tả luồng Kerberos V5 cơ bản, bỏ chi tiết realm, delegation và cơ chế pre-auth cụ thể.',
 ['TGT khác vé dịch vụ.','Vé và authenticator khác nhau.','Kerberos cơ bản không phải hệ dùng public key để mã hóa mọi vé.'],
 'Vì sao không trình TGT trực tiếp để thay mọi service ticket?','TGT dành cho TGS; service ticket được tạo cho đúng SS và có cấu trúc bảo vệ để SS đó xử lý.', ['https://www.rfc-editor.org/info/rfc4120/'])
M('ssh','6','6.7','SSH: xác thực máy chủ trước, rồi người dùng, rồi mở kênh','Ba lớp chức năng của SSH không được nhập thành một bước “gõ mật khẩu”.',[
 N('client','a','SSH client','Khởi tạo kết nối','Ứng dụng phía người dùng muốn dùng dịch vụ máy chủ qua kênh bảo vệ.'),N('host','b','Host key & KEX','Danh tính máy chủ','Trao đổi khóa tạo bí mật phiên; chữ ký/kiểm host key giúp ràng buộc đúng máy chủ.'),N('transport','c','Transport bảo vệ','Mã hóa & toàn vẹn','Các tham số/khóa được dùng để bảo vệ luồng SSH sau thương lượng.'),N('user','f','User authentication','Đúng tài khoản','Máy chủ kiểm người dùng bằng phương thức được cho phép, ví dụ khóa công khai.'),N('channels','e','Connection channels','Shell / forwarding','SSH multiplex nhiều kênh logic trong một kết nối theo quyền và chính sách.')],
 [E('a','client','host','1'),E('b','host','transport','2'),E('c','transport','user','3'),E('d','user','channels','4')],[
 S('Kiểm máy chủ trong trao đổi khóa','Host key gắn với máy chủ, khác khóa xác thực tài khoản của người dùng. Kênh tin cậy trước hoặc cơ chế quản lý khóa cho biết bạn đang tin khóa của ai. Cùng IP hoặc cổng 22 mở chưa chứng minh đúng danh tính.','a'),
 S('Thiết lập transport an toàn','Hai bên thương lượng thuật toán và thiết lập khóa bảo vệ kênh. KEX không có nghĩa gửi private key của người dùng qua mạng. Nếu chấp nhận nhầm host key, bạn vẫn có thể có kết nối được mã hóa nhưng tới sai chủ thể.','b'),
 S('Xác thực người dùng bên trong kênh','Server kiểm phương thức mà chính sách cho phép. Với public-key authentication, client chứng minh sở hữu khóa riêng tương ứng, không gửi nguyên khóa riêng cho server. Thành công chỉ xác nhận tài khoản theo cơ chế đó; quyền làm gì là vấn đề tiếp theo.','c'),
 S('Mở kênh theo nhu cầu và quyền','Connection protocol tạo shell, chạy lệnh hoặc các loại kênh được cho phép. Một kết nối có thể có nhiều kênh, nhưng không có nghĩa mọi chức năng forwarding hoặc mọi quyền hệ thống đều tự được cấp. Giới hạn phiên và quyền vẫn phải cấu hình.','d')],
 'SSH báo host key thay đổi: xác minh qua kênh đáng tin trước khi chấp nhận. Không bỏ qua chỉ vì vẫn đăng nhập được hoặc IP không đổi.',
 'Mô hình SSH-2 tổng quát; chưa vẽ từng packet, rekey hay từng phương thức xác thực. Host key không phải chứng chỉ web X.509 mặc định.',
 ['Khóa host khác khóa tài khoản.','Mã hóa không tự chứng minh đúng host nếu bỏ kiểm khóa.'],
 'Vì sao khóa riêng người dùng không cần được gửi cho server để public-key authentication hoạt động?','Vì client tạo bằng chứng mật mã để server kiểm bằng khóa công khai tương ứng, thay vì tiết lộ bí mật.')
M('otp','3','3.3.4','One-time Pad: vì sao tái sử dụng khóa phá vỡ điều kiện?','Nhìn hai thông điệp khi dùng chung pad; tính an toàn mạnh của OTP có những điều kiện rất chặt.',[
 N('m1','a','Thông điệp m₁','Chuỗi bit','Thông điệp thứ nhất được biểu diễn thành bit.'),N('k','b','Pad K','Ngẫu nhiên, dùng một lần','Pad đúng nghĩa phải ngẫu nhiên độc lập, bí mật, dài ít nhất phần dữ liệu cần mã hóa và không dùng lại.'),N('c1','c','c₁ = m₁ ⊕ K','Bản mã thứ nhất','XOR từng bit thông điệp với pad tạo ciphertext.'),N('m2','d','Thông điệp m₂','Nếu dùng lại cùng K','Nhánh dưới cố tình vi phạm điều kiện một lần để chỉ ra hậu quả.'),N('c2','e','c₂ = m₂ ⊕ K','Bản mã thứ hai','Hai bản mã khi dùng chung K có quan hệ mà người ngoài tính được.'),N('leak','f','c₁ ⊕ c₂ = m₁ ⊕ m₂','Pad bị triệt tiêu','Lộ quan hệ giữa hai plaintext; không còn lập luận bí mật hoàn hảo của OTP đúng điều kiện.')],
 [E('a','m1','k','1'),E('b','k','c1','2'),E('c','m2','c2','3 · dùng lại K'),E('d','c2','leak','4'),E('e','c1','leak','4')],[
 S('OTP đúng nghĩa bắt đầu bằng pad đúng điều kiện','K không chỉ là một mật khẩu được lặp lại cho đủ dài. Ngẫu nhiên, độc lập với thông điệp, bí mật, đủ dài và dùng đúng một lần là những điều kiện cốt lõi. Nếu thay pad ngẫu nhiên bằng luồng sinh từ khóa ngắn, đó là mô hình an toàn khác.','a'),
 S('Mã hóa và giải mã bằng XOR','c=m⊕K; người có K tính c⊕K=m vì K⊕K=0. Cách tính đơn giản không có nghĩa việc quản lý pad đơn giản: hai bên phải phân phối và sử dụng cùng đoạn pad mà không để lộ hoặc tái dùng.','b'),
 S('Xét nhánh sai: tái sử dụng một đoạn pad','Nếu c₁=m₁⊕K và c₂=m₂⊕K, người quan sát có thể XOR hai ciphertext mà không biết K. Khi đó K xuất hiện hai lần và bị triệt tiêu. Không được tiếp tục gọi đây là OTP đúng điều kiện bảo mật.','c'),
 S('Thông tin lộ là quan hệ giữa plaintext','c₁⊕c₂=m₁⊕m₂. Điều này chưa tự cung cấp riêng từng thông điệp, nhưng làm lộ quan hệ và có thể kết hợp với cấu trúc/ngữ cảnh hoặc một plaintext đã biết để suy ra thông điệp kia. OTP cũng không tự cung cấp xác thực: bit ciphertext bị lật gây tác động có cấu trúc lên plaintext.',['d','e'])],
 'm₁=1010, m₂=1100, K=0110 → c₁=1100, c₂=1010. c₁⊕c₂=0110=m₁⊕m₂. Các chuỗi chỉ 4 bit để tính tay, không phải khóa dùng thực tế.',
 'Nhánh dưới là phản ví dụ dùng sai khóa, không phải cách vận hành hợp lệ của OTP. Hình không chứng minh mọi mật mã dòng đều bị phá giống nhau.',
 ['“Dùng một lần” áp dụng cho đoạn pad, không phải chỉ tên ứng dụng.','Bí mật không đồng nghĩa toàn vẹn.'],
 'Biết m₁ và c₁,c₂ trong nhánh dùng chung K có thể suy ra m₂ như thế nào?','Tính m₂=c₁⊕c₂⊕m₁. Đây là hậu quả của việc tái sử dụng cùng đoạn pad.')
M('wifi-4way','7','7.4','WPA2-Personal: bốn thông điệp không gửi mật khẩu qua sóng','PMK có trước; four-way handshake chứng minh biết khóa và tạo khóa theo phiên.',[
 N('pmk','b','PMK có trước','Từ PSK phù hợp','Pairwise Master Key được có từ cấu hình khóa/phương thức tương ứng; ví dụ passphrase WPA2-Personal dùng dẫn xuất có SSID.'),N('sta','d','Station','Máy người dùng','Thiết bị muốn kết nối AP, giữ bí mật cần thiết để tham gia thiết lập khóa.'),N('ap','f','Access Point','Điểm truy cập','AP tham gia four-way handshake và quản lý khóa cho liên kết.'),N('keys','h','PTK / GTK','Unicast / group','Pairwise Transient Key phục vụ cặp STA–AP; Group Temporal Key phục vụ lưu lượng nhóm theo cơ chế.')],
 [E('p','pmk','sta','PMK'),E('q','pmk','ap','PMK'),E('a','ap','sta','1 · ANonce'),E('b','sta','ap','2 · SNonce+MIC'),E('c','ap','sta','3 · MIC, GTK'),E('d','sta','ap','4 · xác nhận'),E('e','sta','keys','khóa'),E('f','ap','keys','khóa')],[
 S('Trước handshake phải có bí mật nền','Trong ví dụ WPA2-Personal dùng passphrase, hai phía tạo PMK theo quy tắc có passphrase và SSID. SSID không phải bí mật; biết tên mạng không cho biết passphrase. Four-way handshake không bắt đầu bằng việc gửi mật khẩu cho AP.',['p','q']),
 S('Thông điệp 1: AP gửi ANonce','AP đưa một giá trị nonce và thông tin điều khiển để bắt đầu lần thiết lập. STA có PMK, tạo SNonce và có các địa chỉ MAC cần thiết để dẫn xuất PTK. MAC ở “địa chỉ MAC” khác MAC trong “Message Authentication Code”.','a'),
 S('Thông điệp 2: STA gửi SNonce và MIC','STA gửi SNonce cùng MIC, tức mã kiểm tra toàn vẹn của bản tin theo khóa con phù hợp. AP dùng thông tin nhận được để dẫn xuất PTK và kiểm MIC. Hai bên không phải gửi nguyên PTK hoặc PMK để chứng minh có cùng bí mật.','b'),
 S('Thông điệp 3: AP xác nhận và phân phối khóa nhóm','Bản tin được bảo vệ về toàn vẹn và có dữ liệu khóa nhóm được bảo vệ theo quy tắc. STA kiểm MIC, thông tin lần trao đổi và cài khóa đúng trạng thái. Không hiểu “có GTK trong bản tin” là GTK được phát công khai dạng không bảo vệ.','c'),
 S('Thông điệp 4: xác nhận hoàn tất','STA phản hồi xác nhận bằng bản tin có MIC. Sau khi hoàn tất các điều kiện thiết lập, hai phía dùng khóa cho lưu lượng phù hợp. Một passphrase dễ đoán vẫn có thể dẫn đến rủi ro đoán khóa ngoại tuyến từ dữ liệu handshake đã có; điều đó khác với mật khẩu được gửi nguyên văn.',['d','e','f'])],
 'Hai máy biết cùng mật khẩu mạng không nhất thiết dùng cùng khóa unicast theo phiên: nonce và địa chỉ tham gia dẫn xuất PTK. Biết SSID đơn thuần không đủ giải nội dung.',
 'Chọn WPA2-Personal; không gộp WPA3-SAE hoặc mọi biến thể Enterprise vào cùng sơ đồ. Chưa vẽ mọi trường, replay counter và chi tiết cài khóa; sơ đồ không hướng dẫn thu thập handshake.',
 ['PMK, PTK, GTK là các vai trò khóa khác nhau.','Four-way handshake không gửi passphrase.','Mã hóa liên kết Wi-Fi không tự là mã hóa đầu cuối tới website.'],
 'Nếu không gửi passphrase, vì sao passphrase yếu vẫn nguy hiểm?','Vì dữ liệu kiểm chứng từ một phiên có thể cho phép thử ứng viên ngoại tuyến trong điều kiện phù hợp; không cần thấy mật khẩu nguyên văn.')
M('enterprise','7','7.3','802.1X / EAP-TLS: AP gác cổng, server xác thực danh tính','Phân biệt ba vai trò và hai giai đoạn: EAP xác thực trước, four-way handshake sau.',[
 N('sta','a','Supplicant','Máy người dùng','Thiết bị có phần mềm EAP và thông tin xác thực, ví dụ chứng chỉ client trong EAP-TLS.'),N('ap','b','Authenticator','AP / thiết bị gác cổng','Điểm truy cập điều khiển quyền đi qua cổng dữ liệu, chuyển thông điệp EAP tới backend.'),N('server','c','Authentication server','Backend EAP / RADIUS','Hệ thống kiểm danh tính và chính sách theo EAP method, thường được tích hợp với RADIUS.'),N('keys','f','Vật liệu khóa','Dẫn xuất theo chuẩn','Kết quả phương thức EAP thành công tạo cơ sở cho các khóa của liên kết; không phải phát mật khẩu cho mọi người.'),N('port','e','Liên kết được mở','Vẫn có phân quyền','Thiết lập khóa và chính sách truy cập hoàn tất trước khi cho lưu lượng tương ứng.')],
 [E('a','sta','ap','1 · EAPOL'),E('b','ap','server','2 · backend'),E('c','server','keys','3 · thành công'),E('d','keys','port','4 · khóa/port')],[
 S('AP chưa cho mọi dữ liệu đi qua','Authenticator cho phép các trao đổi cần để xác thực theo cơ chế trước khi mở quyền truy cập dữ liệu thông thường. Có thể nhìn thấy một SSID và kết nối vô tuyến không đồng nghĩa đã có quyền vào mọi dịch vụ trong LAN.','a'),
 S('Chọn một EAP method cụ thể để hiểu','Với ví dụ EAP-TLS, client và server dùng chứng chỉ theo phương thức để xác thực. AP chuyển các trao đổi giữa supplicant và backend; nó không đơn giản so một mật khẩu chung cho cả lớp. Client phải kiểm đúng danh tính/chứng chỉ server theo cấu hình.','b'),
 S('Thành công tạo cơ sở thiết lập khóa','Vật liệu khóa từ phương thức được dùng theo quy tắc của hệ thống để thiết lập PMK tương ứng. AP nhận thông tin cần cho vai trò của mình qua backend được bảo vệ theo triển khai, không phải mọi máy cùng nhận private key của client.','c'),
 S('Four-way handshake và chính sách mở truy cập','Sau EAP thành công, STA và AP còn thiết lập khóa liên kết, chẳng hạn bằng four-way handshake trong WPA2-Enterprise. Danh tính riêng cho phép thu hồi một người hoặc áp chính sách riêng, nhưng hiệu quả phụ thuộc quản trị chứng chỉ, tài khoản và cấu hình thật.','d')],
 'Một nhân viên rời nhóm: thu hồi credential cá nhân và cập nhật quyền dễ quản lý hơn đổi một mật khẩu chia sẻ cho toàn bộ người dùng. Không suy ra mọi hệ Enterprise đều dùng EAP-TLS; đây chỉ là nhánh được chọn để giải thích.',
 'RADIUS là backend thường gặp, không phải tên khác của EAP. Các EAP method có cơ chế/thuộc tính khác nhau; hình cố định EAP-TLS để tránh đánh đồng.',
 ['AP authenticator khác authentication server.','EAP thành công không có nghĩa mọi quyền ứng dụng đều được cấp.'],
 'AP có phải luôn tự kiểm mật khẩu người dùng thay server không?','Không. Trong mô hình này nó điều khiển truy cập và chuyển EAP tới backend xác thực.')
M('stateful','8','8.2.3','Stateful firewall: vì sao gói phản hồi được phép quay vào?','Theo một kết nối TCP được chính sách cho phép; bảng trạng thái không phải danh sách mọi gói “an toàn”.',[
 N('lan','a','Client LAN','Khởi tạo TCP','Máy trong mạng gửi SYN đến server theo đích/cổng đã chọn.'),N('rules','b','Rule & state','Quyết định firewall','Luật cho biết kết nối mới nào được phép; trạng thái lưu diễn biến luồng được theo dõi.'),N('server','c','Server ngoài','SYN-ACK / dữ liệu','Server phản hồi theo ngữ cảnh phiên TCP.'),N('state','e','Bảng trạng thái','Tuple, trạng thái, timeout','Thông tin luồng gồm địa chỉ, cổng, giao thức và trạng thái liên quan theo triển khai.'),N('return','d','Client nhận','Phản hồi hợp lệ','Gói quay vào được xét dựa chính sách và trạng thái, không vì mọi gói từ ngoài đều được tin.')],
 [E('a','lan','rules','1 · SYN'),E('b','rules','server','2 · cho qua'),E('c','rules','state','3 · ghi state'),E('d','server','state','4 · phản hồi'),E('e','state','return','5 · khớp')],[
 S('Kết nối mới vẫn phải qua rule','Firewall nhận SYN từ LAN và xét chính sách áp dụng. Stateful không có nghĩa client bên trong được phép mở mọi đích. Nếu chính sách chặn, không được tạo một đường vào chỉ vì gói phát từ LAN.','a'),
 S('Tạo trạng thái cho luồng được phép','Khi luồng được chấp nhận, hệ thống theo dõi tuple và diễn biến theo khả năng triển khai. Tuple thường liên quan địa chỉ nguồn/đích, cổng nguồn/đích và giao thức. Cổng nguồn của client là một phần của việc phân biệt nhiều kết nối.',['b','c']),
 S('Đối chiếu gói phản hồi','SYN-ACK hoặc dữ liệu trở về được so với luồng theo dõi, chiều truyền, trạng thái và các kiểm tra giao thức phù hợp. Không phải chỉ nhìn một bit ACK rồi mặc định cho qua. Kết quả còn chịu quy tắc và cách tracking của firewall.','d'),
 S('Không khớp hoặc hết hạn thì xét như luồng khác','Gói không thuộc luồng hợp lệ không được hưởng quyền “phản hồi” của luồng trước. Khi kết nối đóng hoặc timeout, trạng thái bị loại theo quy tắc. Dù luồng hợp lệ, nội dung ứng dụng vẫn có thể độc hại nếu không có lớp kiểm tra phù hợp.','e')],
 'Client 192.168.1.10:51514 nối server:443. Gói trả về đúng phiên có thể được cho qua, còn một kết nối mới không được yêu cầu từ Internet vào cổng khác vẫn bị chặn theo chính sách minh họa.',
 'Không vẽ NAT hoặc mọi cờ TCP/sequence number. Stateful không bảo đảm xác thực người dùng hay phát hiện mọi tấn công trong ứng dụng.',
 ['Stateful khác chỉ lọc packet độc lập.','Có state không nghĩa mọi byte của phiên lành tính.'],
 'Gói có ACK nhưng không thuộc phiên theo dõi có tự được cho qua không?','Không. Quyết định phải dựa chính sách và ngữ cảnh trạng thái, không chỉ tên một cờ.')
M('pat','8','8.3','PAT: nhiều máy dùng một địa chỉ ngoài nhờ bảng ánh xạ','Đi cả chiều gửi lẫn chiều trả lời để hiểu vai trò của cổng, không gộp NAT với firewall.',[
 N('lan','a','192.168.1.10:51514','Nguồn trong LAN','Địa chỉ/cổng nguồn của một kết nối trước dịch địa chỉ.'),N('nat','b','Thiết bị PAT','Sửa địa chỉ & cổng','Port Address Translation ánh xạ tuple nội bộ sang tuple bên ngoài.'),N('internet','c','198.51.100.20:443','Server đích','Server nhìn thấy nguồn là tuple đã dịch, không phải địa chỉ private ban đầu.'),N('map','e','Bảng ánh xạ','51514 ↔ 40001','Ví dụ gắn 192.168.1.10:51514 với 203.0.113.7:40001 trong ngữ cảnh kết nối.'),N('reply','d','Máy LAN nhận lại','Dịch ngược','Gói về được ánh xạ lại đến nguồn nội bộ theo trạng thái và chính sách.')],
 [E('a','lan','nat','1'),E('b','nat','internet','2 · nguồn mới'),E('c','nat','map','3 · mapping'),E('d','internet','map','4 · trả lời'),E('e','map','reply','5 · dịch ngược')],[
 S('Gói ban đầu có cả nguồn và đích','Client gửi từ 192.168.1.10:51514 đến 198.51.100.20:443. Địa chỉ IP cho biết máy/mạng; cổng hỗ trợ phân biệt điểm giao tiếp transport. Chỉ ghi địa chỉ IP mà bỏ cổng sẽ không đủ mô tả ví dụ PAT này.','a'),
 S('Thay tuple nguồn ra ngoài','PAT chọn nguồn ngoài 203.0.113.7:40001 và điều chỉnh các trường liên quan theo cơ chế. Server đích phản hồi đến nguồn mà nó thấy. Nội dung ứng dụng không vì NAT mà tự được mã hóa.','b'),
 S('Lưu cách tìm về nguồn gốc','Bảng ghi quan hệ giữa tuple nội bộ và bên ngoài cùng thông tin cần cho kiểu mapping/luồng. Nhiều máy có thể dùng cùng IP ngoài với cổng ngoài khác nhau; không có nghĩa chúng trở thành một tiến trình hoặc một người dùng duy nhất.','c'),
 S('Đổi đích của gói về và kiểm chính sách','Gói trả về gửi tới 203.0.113.7:40001. Thiết bị tra ánh xạ phù hợp và chuyển đích lại thành 192.168.1.10:51514. Khi mapping hết hạn hoặc không tồn tại, nó không có cơ sở chuyển theo ánh xạ này. Việc cho phép vẫn khác với chính chức năng dịch.',['d','e'])],
 'Một máy khác có thể có nguồn trong LAN khác nhưng cùng dùng 203.0.113.7 với cổng ngoài khác. Các IP ngoài trong ví dụ là địa chỉ tài liệu, không phải máy thật để thử kết nối.',
 'Hình chọn source PAT động. NAT tĩnh, DNAT/port forwarding và các loại mapping khác có hành vi riêng; không suy ra mọi NAT chặn mọi kết nối vào.',
 ['NAT không phải mã hóa.','Dịch địa chỉ không tự thay chính sách firewall.'],
 'Vì sao chỉ biết IP ngoài chưa đủ xác định máy LAN nhận gói trả lời?','Vì nhiều tuple nội bộ có thể chia sẻ IP ngoài; cần cổng/giao thức và ngữ cảnh mapping phù hợp.')
M('dmz','8','8.4','DMZ: công khai dịch vụ mà vẫn giữ ranh giới LAN','Không chỉ vẽ ba vùng: hãy đọc luật cho từng chiều và từng dịch vụ.',[
 N('net','a','Internet','Nguồn không tin cậy','Nơi người dùng công khai truy cập dịch vụ được công bố.'),N('outer','b','Kiểm soát ngoài','Chỉ luồng cần thiết','Có thể là giao diện/vùng của firewall hoặc thiết bị riêng theo kiến trúc.'),N('web','c','Web server DMZ','Dịch vụ công khai','Máy chủ phải nhận một số kết nối Internet nhưng không được xem như hoàn toàn tin cậy.'),N('inner','f','Kiểm soát DMZ–LAN','Quyền tối thiểu','Chỉ cho luồng được yêu cầu rõ giữa dịch vụ DMZ và tài nguyên bên trong.'),N('db','e','Database LAN','Không công khai trực tiếp','Cơ sở dữ liệu được tách khỏi truy cập trực tiếp từ Internet trong ví dụ.'),N('admin','d','Quản trị tin cậy','Đường quản trị riêng','Điểm quản trị phải chịu xác thực, phân quyền và kiểm soát đường vào theo thiết kế.')],
 [E('a','net','outer','1'),E('b','outer','web','2 · HTTPS'),E('c','web','inner','3 · yêu cầu DB'),E('d','inner','db','4 · đúng luồng'),E('e','admin','db','5 · quản trị')],[
 S('Internet chỉ tới dịch vụ công khai','Luật ngoài cho phép luồng cần thiết, ví dụ HTTPS đến đúng web server DMZ. Không mở cùng cổng đó tới mọi host hoặc coi có DMZ là có thể bỏ kiểm tra server công khai. Server này vẫn cần vá lỗi và gia cố.',['a','b']),
 S('DMZ được coi là vùng có thể bị xâm hại','Nếu web server bị chiếm, ranh giới trong phải giới hạn nó có thể tiếp cận những gì. DMZ không làm server bất khả xâm nhập; giá trị của nó là giảm tin cậy và cô lập ảnh hưởng so với đặt thẳng dịch vụ công khai trong LAN.','c'),
 S('Chỉ cấp luồng backend cần thiết','Nếu ứng dụng cần DB, mở đúng nguồn web, đúng đích DB, giao thức/cổng và chiều theo nhu cầu. Kết nối đã cho phép vẫn có thể mang truy vấn độc hại nếu web bị chiếm, nên cần tài khoản DB ít quyền và kiểm soát ứng dụng.','d'),
 S('Tách đường quản trị và giám sát','Luồng quản trị không nên được mở tùy ý từ Internet vì tiện. Thiết kế đường tin cậy, xác thực mạnh, ghi log và kiểm soát quyền phù hợp. “Không có mũi tên Internet→DB” trong hình biểu đạt chính sách mong muốn, không tự tạo ra luật trên thiết bị.','e')],
 'Cho Internet→Web:443. Cho Web→DB chỉ khi ứng dụng thực sự cần và đúng cổng đã xác định. Không cho Web→mọi host LAN. Nếu DB chỉ cần quyền đọc cho chức năng đó, không cấp quyền quản trị DB.',
 'Hai hộp kiểm soát là hai ranh giới logic; có thể dùng một firewall nhiều vùng hoặc nhiều thiết bị. Mũi tên biểu diễn luồng được chọn để giải thích, không liệt kê mọi lưu lượng DNS, cập nhật hay phản hồi.',
 ['DMZ không phải vùng hoàn toàn đáng tin.','Rule DMZ→LAN any làm suy yếu mục đích phân tách.'],
 'Nếu web DMZ bị chiếm, lớp DMZ–LAN còn có ích gì?','Nó có thể giới hạn đường tiếp cận sang LAN, giảm phạm vi tác động; nhưng phải kết hợp quyền backend và kiểm soát khác.')
M('proxy','8','8.2.4','Proxy: hai kết nối thay vì chuyển một kết nối nguyên vẹn','Theo điểm kết thúc phiên và phân biệt chuyển tiếp với kiểm tra nội dung TLS.',[
 N('client','a','Client','Kết nối tới proxy','Client gửi yêu cầu cho proxy theo cơ chế cấu hình/triển khai.'),N('proxy','b','Proxy ứng dụng','Nhận và quyết định','Proxy xử lý yêu cầu theo giao thức mà nó hỗ trợ và áp chính sách.'),N('server','c','Server đích','Kết nối từ proxy','Trong mô hình proxy kết thúc phiên, server thấy kết nối do proxy tạo.'),N('policy','e','Chính sách / log','Danh tính, đích, nội dung','Khả năng kiểm tra thực tế phụ thuộc proxy có nhìn được dữ liệu nào và có được phép xử lý chúng không.')],
 [E('a','client','proxy','1 · phiên A'),E('b','proxy','server','2 · phiên B'),E('c','server','proxy','3 · phản hồi'),E('d','proxy','client','4 · trả về'),E('e','proxy','policy','kiểm tra')],[
 S('Client không nhất thiết kết nối trực tiếp server','Trong mô hình này, phiên transport/ứng dụng của client kết thúc tại proxy. Proxy có thể nhận danh tính client, kiểm đích hoặc áp quy tắc giao thức. Đây khác với một router chỉ quyết định next hop của gói.','a'),
 S('Proxy tạo một phiên riêng tới đích','Proxy đóng vai client đối với server. Hai phiên có trạng thái riêng; nó không chỉ viết lại một trường IP như mô hình PAT. Tuy vậy cách dùng từ “proxy” rộng: reverse proxy và forward proxy có hướng phục vụ khác nhau.','b'),
 S('Phản hồi đi qua điểm kiểm soát','Proxy nhận phản hồi từ server, có thể áp chính sách phù hợp rồi gửi về client. Khả năng xem nội dung tùy giao thức và cấu hình. Một đường hầm HTTPS CONNECT không tự đồng nghĩa proxy đọc được plaintext HTTP bên trong TLS.',['c','d']),
 S('Muốn kiểm tra TLS phải có mô hình tin cậy khác','Nếu một hệ thống kết thúc và thiết lập lại TLS để kiểm tra nội dung, nó tạo hai quan hệ TLS và cần cấu hình tin cậy/quyền phù hợp ở client. Không được đánh đồng với chuyển tiếp TLS nguyên vẹn. Cần mô tả rõ proxy nhìn được gì trước khi kết luận khả năng lọc.','e')],
 'Forward proxy phục vụ người dùng ra Internet; reverse proxy đứng trước dịch vụ phục vụ khách. Cả hai có thể áp chính sách nhưng không vì tên gọi mà tự thấy mọi nội dung đã mã hóa.',
 'Hình chọn proxy ứng dụng kết thúc phiên; chưa mô tả mọi kiểu tunneling, transparent proxy hoặc cache. Không suy ra mọi proxy đều giải mã TLS.',
 ['Proxy không đồng nghĩa NAT.','CONNECT tunnel khác TLS inspection.'],
 'Tại sao một proxy chuyển đường hầm HTTPS chưa chắc chặn được một từ trong trang?','Vì nó có thể không có plaintext ứng dụng để kiểm tra từ đó; chỉ thấy thông tin của lớp/kênh mà nó quan sát được.')
