deep = {
 'feistel': [
  ('Bên trong F: độ dài thay đổi ở đâu?', 'E mở rộng R từ 32 lên 48 bit bằng cách chọn/lặp một số bit theo bảng, không tạo thêm thông tin bí mật. XOR với Kᵢ giữ độ dài 48 bit. Chia thành 8 nhóm, mỗi nhóm 6 bit đi qua một S-box để nhận 4 bit: 8×4=32 bit. P chỉ đổi vị trí 32 bit đó. Vì thế F nhận nửa khối 32 bit nhưng khóa con có 48 bit.'),
  ('Đọc một đầu vào S-box', 'Với nhóm 6 bit b₁b₂b₃b₄b₅b₆, lấy b₁b₆ làm chỉ số hàng 0..3 và b₂b₃b₄b₅ làm chỉ số cột 0..15. Tra đúng S-box tương ứng với vị trí nhóm, rồi biểu diễn kết quả thành 4 bit. Ví dụ 011011 chọn hàng 01₂=1, cột 1101₂=13. Không dùng cả sáu bit làm chỉ số cột, cũng không dùng cùng một bảng S-box cho cả tám nhóm.')],
 'aes': [
  ('ShiftRows: thấy rõ từng hàng', 'Giả sử bốn hàng chứa [a b c d], [e f g h], [i j k l], [m n o p]. Sau ShiftRows của chiều mã hóa, chúng thành [a b c d], [f g h e], [k l i j], [p m n o]. Chữ chỉ đại diện byte, không phải phép cộng ký tự. Một byte chuyển vị trí nhưng chưa bị thay giá trị ở chính phép này.'),
  ('MixColumns: công thức một cột', 'Với cột (a₀,a₁,a₂,a₃), byte đầu ra đầu tiên là b₀=(02·a₀)⊕(03·a₁)⊕a₂⊕a₃. Ba hàng hệ số tiếp theo là [01 02 03 01], [01 01 02 03], [03 01 01 02]. Các hệ số là byte hex; tích nằm trong GF(2⁸), phép cộng là XOR. Giảm đa thức theo x⁸+x⁴+x³+x+1, không lấy modulo số nguyên 256. Nhân 03 với a có thể viết (02·a)⊕a. Vòng cuối bỏ phép này.'),
  ('Khóa vòng đến từ đâu?', 'Ở AES-128, khóa gốc gồm 4 word, mỗi word 4 byte. Key expansion tạo 44 word, ghép từng 4 word thành 11 khóa vòng 16 byte. Tại bước đặc biệt của lịch khóa có RotWord, SubWord và hằng số Rcon, kết hợp XOR với word trước phù hợp. Khóa vòng được dẫn xuất từ khóa gốc, không từ ciphertext. AddRoundKey XOR từng byte tương ứng của state và khóa vòng; kích thước hai đầu vào phải khớp.')],
 'rsa': [
  ('Vì sao cần biểu diễn thông điệp và padding?', 'Công thức c=mᵉ mod n thao tác trên một số nguyên trong khoảng quy định, không trực tiếp trên một câu tiếng Việt tùy độ dài. Hệ thực mã hóa byte theo một scheme chuẩn trước khi áp phép RSA. RSA trần có tính xác định: cùng m và public key cho cùng c, nên tập đầu vào nhỏ có thể bị đối chiếu ứng viên. Không khắc phục bằng việc giữ bí mật e; e vốn là tham số công khai.')],
 'dh': [
  ('Hai bên cùng số 2 nhưng không gửi số 2', 'Alice nhận B=19 rồi tính B⁶ mod23; Bob nhận A=8 rồi tính A¹⁵ mod23. Hai kết quả trùng do phép lũy thừa trong cùng nhóm, không do so sánh bí mật qua mạng. Trong một giao thức thực, bí mật chia sẻ cùng transcript/ngữ cảnh có thể được đưa vào KDF để tạo các khóa riêng biệt cho từng mục đích. Không dùng trực tiếp cách viết số thập phân 2 làm mật khẩu hay khóa AES.'),
  ('Tại sao xác thực phải ràng buộc đúng cuộc trao đổi?', 'Nếu chỉ kiểm danh tính ở một thông điệp không gắn với các giá trị A,B và ngữ cảnh phiên, người nhận có thể xác thực một thứ nhưng dùng khóa của cuộc trao đổi khác. Giao thức cần ràng buộc bằng chứng danh tính với thông số và transcript phù hợp. Vì thế không tự ghép “DH rồi thêm một chữ ký bất kỳ” mà coi như đã có một giao thức an toàn.')],
 'mac': [
  ('Bên trong HMAC: hash lồng có khóa', 'Dạng cấu trúc: HMAC(K,m)=H((K′⊕opad) || H((K′⊕ipad) || m)). H là hàm băm; || là nối byte. Chuẩn hóa K thành K′ dài bằng kích thước block của H: nếu khóa quá dài thì băm trước, sau đó đệm 0 cho đủ block. ipad là byte 0x36 lặp lại, opad là 0x5c lặp lại. Hash trong xử lý lớp khóa trong và m; hash ngoài xử lý lớp khóa ngoài và digest trong. Đây không phải checksum, không phải đơn giản H(K||m).'),
  ('Vì sao có tag đúng mà vẫn cần số thứ tự?', 'Người nhận dùng HMAC kiểm nội dung và ngữ cảnh được đưa vào phép tính. Nếu số thứ tự chỉ gửi ở ngoài nhưng không được xác thực, dữ liệu bảo vệ có thể không ràng buộc đúng trạng thái. Nếu một thông điệp hợp lệ cũ được dùng lại, tag vẫn có thể đúng; máy nhận cần kiểm thêm số thứ tự/nonce và trạng thái phiên để tránh thực hiện lại yêu cầu.')],
 'pki': [
  ('Xây đường chứng chỉ khác với tin mọi khóa gửi đến', 'Leaf certificate của máy chủ có thể do intermediate CA ký; intermediate lại được một CA khác chứng nhận, đi đến trust anchor mà bên kiểm đã có lý do tin. Bên kiểm xác minh từng chữ ký và các ràng buộc đường dẫn/mục đích, không chỉ nối những tên giống nhau. Trust anchor không trở nên đáng tin chỉ vì nó tự ký; việc được cấu hình/trao tin ban đầu mới là cơ sở.'),
  ('Nếu private key bị lộ thì sao?', 'Người sở hữu phải xử lý thay khóa/chứng chỉ và thu hồi theo quy trình, đồng thời đánh giá các phiên/dữ liệu chịu ảnh hưởng. CRL hoặc OCSP là cơ chế thông báo trạng thái theo triển khai; không tự xóa khóa đã bị đánh cắp khỏi máy đối phương, cũng không tự làm bí mật trở lại những dữ liệu đã bị đọc.')],
 'tls': [
  ('Transcript và khóa cho từng mục đích', 'Transcript là bản ghi mật mã của các thông điệp handshake theo quy tắc TLS. Dẫn xuất bằng HKDF gắn khóa với bí mật và ngữ cảnh, phân biệt khóa handshake/ứng dụng và hai chiều gửi. CertificateVerify ràng buộc quyền sở hữu khóa ký vào ngữ cảnh handshake; Finished dùng khóa xác nhận để kiểm transcript. Đây là hai kiểm tra liên quan nhưng không đồng nhất.'),
  ('AEAD bảo vệ record ra sao?', 'AEAD nhận khóa, nonce, plaintext và dữ liệu liên quan để tạo ciphertext/tag. Phần liên quan được xác thực nhưng không nhất thiết mã hóa. Đầu nhận chỉ được sử dụng plaintext theo quy tắc sau khi xác minh hợp lệ; đổi bit ciphertext hoặc thông tin liên quan được bảo vệ sẽ làm kiểm tra tag thất bại với xác suất giả mạo bị giới hạn. Quy tắc nonce/sequence number của giao thức là một phần của an toàn, không phải chi tiết có thể bỏ qua.')],
 'kerberos': [
  ('Ai mở được vé nào? — nhánh khóa đối xứng minh họa', 'Ký hiệu Kc,tgs là khóa phiên client–TGS, Kc,ss là khóa phiên client–dịch vụ. TGT được bảo vệ bằng khóa dài hạn của TGS và mang Kc,tgs cùng thông tin vé; client cầm TGT nhưng không cần tự mở nó. Phần AS trả cho client được bảo vệ theo cơ chế xác thực ban đầu, trong nhánh mật khẩu cơ bản liên quan khóa dài hạn của client. Service ticket được bảo vệ cho SS và chứa Kc,ss; phần phản hồi TGS cho client được bảo vệ bằng Kc,tgs. Tên khóa không chỉ tên máy gửi packet mà chỉ quan hệ bảo vệ.'),
  ('Vé khác authenticator ở tính mới', 'Vé có thời hạn để tái sử dụng theo quy tắc, còn authenticator được client tạo mới bằng khóa phiên tương ứng và mang thông tin như thời điểm để server kiểm. Nếu chỉ trình lại nguyên một yêu cầu cũ, kiểm replay/timestamp và replay cache phải giúp loại nó. Nếu cả vé lẫn khóa phiên bị đánh cắp, rủi ro khác với việc chỉ nhìn thấy vé trên đường truyền; vì vậy phải bảo vệ cache/khóa trên đầu cuối.')],
 'wifi-4way': [
  ('PMK, PTK, KCK, KEK và TK nối nhau thế nào?', 'Viết sơ đồ ý niệm: PTK=KDF(PMK, địa chỉ AP, địa chỉ STA, ANonce, SNonce), với cách sắp xếp/định dạng chính xác theo chuẩn. PTK gồm các phần có vai trò riêng: KCK dùng cho MIC của trao đổi khóa; KEK bảo vệ thông tin khóa như việc chuyển GTK; TK dùng cho bảo vệ dữ liệu unicast theo cipher. GTK là khóa nhóm do AP quản lý, không đồng nghĩa toàn bộ PTK. Đây là sơ đồ vai trò, không phải công thức đủ để tự triển khai KDF.'),
  ('Wi-Fi và HTTPS bảo vệ hai đoạn khác nhau', 'Bảo vệ WPA2 liên kết thiết bị–AP không mặc nhiên kéo dài tới máy chủ Internet. AP là một đầu của bảo vệ liên kết và còn chuyển dữ liệu đi tiếp. TLS có thể tạo lớp bảo vệ giữa ứng dụng client và server qua cả AP. Ghép hai lớp không thừa: mỗi lớp có phạm vi tin cậy và điểm kết thúc khác nhau.')]
}
